/* Flash cards USMLE: Gastrointestinal (791 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["gastrointestinal"] = [{"name":"Anatomy","cards":[["317r8l3tu","What are the four layers of the gut wall from inside out?","Mucosa, submucosa, muscularis externa, serosa (adventitia when retroperitoneal).","Mucosa, submucosa, muscular e serosa."],["dkwmnr1ni","What are the three layers of the mucosa?","Epithelium (absorption), lamina propria (support), muscularis mucosa (motility).","Epitélio, lâmina própria e muscular da mucosa."],["1bbsa7y22","Which nerve plexus is located in the submucosa and what does it control?","Meissner (submucosal) plexus; controls secretions, blood flow, and absorption.","Plexo de Meissner: secreção e fluxo."],["m7q9sk1xd","Which nerve plexus is between the muscle layers and what does it control?","Myenteric (Auerbach) plexus; controls motility.","Plexo de Auerbach: motilidade."],["doh3i2nkx","Which structures are retroperitoneal?","SAD PUCKER: Suprarenal glands, Aorta and IVC, Duodenum (2nd-4th parts), Pancreas (except tail), Ureters, Colon (ascending and descending), Kidneys, Esophagus (thoracic), Rectum (partially).","Órgãos retroperitoneais."],["2glh9dpc4","What is the clinical significance of retroperitoneal structures?","Injuries can cause blood or gas accumulation in the retroperitoneal space.","Sangramento ou gás no retroperitônio."],["j9arkns0f","What does the falciform ligament connect and contain?","Liver to anterior abdominal wall; contains ligamentum teres hepatis (remnant of umbilical vein) and patent paraumbilical veins.","Liga fígado à parede; ligamento redondo."],["1mommvi1k","What does the hepatoduodenal ligament contain?","Portal triad: proper hepatic artery, portal vein, common bile duct.","Tríade portal."],["1bvmgb1s1","What is the Pringle maneuver?","Compression of the hepatoduodenal ligament to control hepatic bleeding.","Compressão do ligamento hepatoduodenal."],["2o71wxjzw","What is the boundary of the omental foramen (epiploic foramen of Winslow)?","Connects the greater and lesser sacs; anterior boundary is the hepatoduodenal ligament.","Ligamento hepatoduodenal na frente."],["9437ije4u","What does the gastrohepatic ligament contain?","Gastric arteries (left and right); part of the lesser omentum.","Artérias gástricas."],["1msm9nn1v","What does the gastrocolic ligament contain?","Gastroepiploic arteries; part of the greater omentum.","Artérias gastroepiploicas."],["1h5l92f97","What does the gastrosplenic ligament contain?","Short gastric and left gastroepiploic vessels.","Artérias gástricas curtas."],["jdcje2dtm","What does the splenorenal ligament contain?","Splenic artery and vein, tail of the pancreas.","Artéria esplênica e cauda do pâncreas."],["1xjy3291q","What are the main features of esophageal histology?","Nonkeratinized stratified squamous epithelium; upper third skeletal muscle, middle mixed, lower third smooth muscle.","Epitélio escamoso; músculo misto."],["nva8go10c","What is the histology of the stomach?","Gastric glands with parietal cells (acid, intrinsic factor) and chief cells (pepsinogen); rugae.","Células parietais e principais."],["9jdu1qv7r","What is the histology of the duodenum?","Villi and microvilli increase absorptive surface; Brunner glands (bicarbonate-secreting mucus) in submucosa; crypts of Lieberkühn.","Vilosidades e glândulas de Brunner."],["13p5dldso","What is the histology of the jejunum?","Plicae circulares (feathered appearance on contrast imaging) and crypts of Lieberkühn.","Pregas circulares."],["1t1ev9rm1","What is the histology of the ileum?","Peyer patches (lymphoid aggregates in lamina propria and submucosa), plicae circulares (proximal), crypts of Lieberkühn; most goblet cells in small intestine.","Placas de Peyer."],["1wqs4yen3","What is the histology of the colon?","Crypts of Lieberkühn with abundant goblet cells, no villi.","Criptas com muitas células caliciformes."],["13dqi1mhf","What are the branches of the celiac trunk?","Left gastric, splenic, common hepatic arteries.","Gástrica esquerda, esplênica e hepática comum."],["1vmw09l1f","What does the common hepatic artery give rise to?","Proper hepatic artery, gastroduodenal artery (and right gastric often).","Hepática própria e gastroduodenal."],["1jpj4jv7q","Which artery is at risk with a posterior duodenal ulcer?","Gastroduodenal artery (massive hemorrhage).","Artéria gastroduodenal."],["qonbi6jk4","Which artery is at risk with an ulcer on the lesser curvature of the stomach?","Left gastric artery.","Artéria gástrica esquerda."],["1bxkbe2wg","Which artery supplies the greater curvature of the stomach?","Right and left gastroepiploic arteries.","Artérias gastroepiploicas."],["u1wr6q14f","Which arteries supply the fundus of the stomach?","Short gastric arteries (from splenic artery); poor collaterals, vulnerable to infarction if splenic artery is occluded.","Gástricas curtas, sem colaterais."],["d798jm6x5","What does the superior mesenteric artery supply?","Midgut: distal duodenum to proximal two-thirds of transverse colon.","Intestino médio."],["1m96cwlga","What does the inferior mesenteric artery supply?","Hindgut: distal third of transverse colon to upper rectum.","Intestino posterior."],["148stb01q","What are watershed areas of the colon?","Splenic flexure (SMA and IMA border) and rectosigmoid junction (Sudeck point, IMA and internal iliac); vulnerable in hypotension.","Flexura esplênica e retossigmoide."],["1n0puq71o","What is the vertebral level of the celiac trunk?","T12.","T12."],["10k6ghznt","What is the vertebral level of the SMA?","L1.","L1."],["10jyh5pns","What is the vertebral level of the IMA?","L3.","L3."],["1foxazytb","What is the vertebral level of the aortic bifurcation?","L4 (at the umbilicus level).","L4."],["19hf6qo7a","What is SMA syndrome?","Compression of the 3rd part of the duodenum between the aorta and SMA, causing intestinal obstruction; associated with rapid weight loss, decreased mesenteric fat.","Duodeno comprimido entre aorta e AMS."],["1u47cqu1p","What is the nutcracker syndrome?","Compression of the left renal vein between the aorta and SMA: abdominal/flank pain, hematuria, left varicocele.","Veia renal esquerda comprimida."],["1hfd3oc17","What are the major portosystemic anastomoses?","Esophagus (left gastric to esophageal veins), umbilicus (paraumbilical to superficial epigastric veins), rectum (superior rectal to middle and inferior rectal veins).","Esôfago, umbigo e reto."],["pty7vdgou","What clinical signs result from portosystemic anastomoses in portal hypertension?","Esophageal varices, caput medusae, anorectal varices.","Varizes, cabeça de medusa, varizes retais."],["2tx7ag1qf","What is the treatment that shunts blood from the portal vein to the hepatic vein?","TIPS (transjugular intrahepatic portosystemic shunt); may precipitate hepatic encephalopathy.","TIPS."],["1om72ek1x","What forms the portal vein?","Union of the superior mesenteric vein and splenic vein (behind the pancreatic neck).","Veias mesentérica superior e esplênica."],["z4ctgsdos","Where does the inferior mesenteric vein drain?","Into the splenic vein (usually).","Veia esplênica."],["18u79ew17","What is the pectinate line?","Where the endoderm (hindgut) meets ectoderm in the anal canal.","Encontro de endoderma e ectoderma."],["iqcxc584g","What are the blood supplies above and below the pectinate line?","Above: superior rectal artery (IMA). Below: inferior rectal artery (internal pudendal).","Retal superior acima; inferior abaixo."],["1e33ypa13","What are the venous drainages above and below the pectinate line?","Above: superior rectal vein to IMV to splenic to portal vein. Below: inferior rectal vein to internal pudendal to internal iliac to IVC.","Porta acima; cava abaixo."],["1jqilneu9","What is the lymphatic drainage above and below the pectinate line?","Above: internal iliac nodes. Below: superficial inguinal nodes.","Ilíacos internos acima; inguinais abaixo."],["34hjtwuj7","Why are internal hemorrhoids painless?","They are above the pectinate line with visceral innervation.","Inervação visceral."],["1ar4povnj","What is an anal fissure and where does it usually occur?","Tear in the anoderm below the pectinate line; posterior midline (poorly perfused); painful bleeding with defecation.","Fissura na linha média posterior."],["1cm08t8qb","What are the lobes of the liver?","Right, left, caudate, quadrate lobes; functionally 8 Couinaud segments.","Quatro lobos e 8 segmentos."],["1rb3ctq38","What is zone I of the hepatic lobule and what affects it?","Periportal zone; affected first by viral hepatitis and ingested toxins (e.g., cocaine).","Zona I: vírus e toxinas ingeridas."],["p9ouyv28h","What is zone II of the hepatic lobule and what affects it?","Intermediate zone; yellow fever.","Zona II: febre amarela."],["19wtbim1i","What is zone III of the hepatic lobule and what affects it?","Pericentral (centrilobular) zone; first affected by ischemia, contains cytochrome P450, most sensitive to metabolic toxins (ethanol, acetaminophen, CCl4); site of alcoholic hepatitis.","Zona III: isquemia e toxinas metabólicas."],["uf242y1w8","What are Kupffer cells?","Specialized macrophages lining the hepatic sinusoids.","Macrófagos do fígado."],["j7c58wkwk","What are hepatic stellate (Ito) cells?","Store vitamin A in the space of Disse; when activated, produce extracellular matrix causing fibrosis.","Armazenam vitamina A; causam fibrose."],["1omn3fai3","What is the space of Disse?","Perisinusoidal space between hepatocytes and sinusoidal endothelium where lymph drains.","Espaço entre hepatócito e sinusoide."],["1ciytxj1s","What is the path of bile flow?","Hepatocytes to bile canaliculi, bile ductules, hepatic ducts, common hepatic duct, joins cystic duct to form common bile duct, to the ampulla of Vater.","Caminho da bile até o duodeno."],["1dpbvpll1","What sphincter controls bile and pancreatic juice into the duodenum?","Sphincter of Oddi at the ampulla of Vater (major duodenal papilla).","Esfíncter de Oddi."],["it38nyirn","What happens with a tumor at the head of the pancreas?","Obstruction of the common bile duct: painless jaundice and palpable gallbladder (Courvoisier sign).","Icterícia indolor e vesícula palpável."],["1pa45qln5","What is Calot triangle (cystohepatic triangle)?","Bounded by cystic duct, common hepatic duct, and inferior liver edge; contains the cystic artery.","Contém a artéria cística."],["7hpj691u4","What is the location of the femoral triangle and its contents?","Bounded by inguinal ligament, sartorius, adductor longus; contains femoral nerve, artery, vein (lateral to medial: NAVEL).","Nervo, artéria, veia, linfáticos."],["1qok4ex17","What does the femoral sheath contain?","Femoral artery, vein, and canal (lymphatics), but not the femoral nerve.","Artéria, veia e canal femoral."],["14gnw4p1z","What is an indirect inguinal hernia?","Goes through the internal (deep) inguinal ring, external ring, and into the scrotum; lateral to inferior epigastric vessels; due to patent processus vaginalis; common in infants.","Lateral aos epigástricos; processo vaginal."],["1mim56od3","What is a direct inguinal hernia?","Protrudes through the inguinal (Hesselbach) triangle medial to the inferior epigastric vessels; bulges through the external ring only; older men.","Medial aos epigástricos; homens idosos."],["1fz80q215","What are the boundaries of Hesselbach triangle?","Inferior epigastric vessels, lateral border of rectus abdominis, inguinal ligament.","Limites do triângulo de Hesselbach."],["jroqy416w","What is a femoral hernia?","Protrudes below the inguinal ligament through the femoral canal lateral to the pubic tubercle; more common in females; most likely to incarcerate.","Abaixo do ligamento inguinal; mulheres."],["8mo31g1md","Mnemonic for direct vs indirect inguinal hernia relative to inferior epigastric vessels?","MDs don't lie: Medial to inferior epigastric = Direct; lateral = indirect.","Medial = direta."],["125coj51g","What layers of the spermatic cord derive from which abdominal layers?","External spermatic fascia (external oblique aponeurosis), cremasteric muscle and fascia (internal oblique), internal spermatic fascia (transversalis fascia).","Camadas do cordão espermático."],["a14we11dx","What is a sliding hiatal hernia?","Gastroesophageal junction displaced upward through the diaphragm (hourglass stomach); most common type; associated with GERD.","Junção esofagogástrica sobe."],["1der8vaug","What is a paraesophageal hiatal hernia?","GE junction remains in place but the gastric fundus protrudes into the thorax; risk of strangulation.","Fundo gástrico sobe; risco de estrangulamento."],["za5b0i1s8","What are the parts of the duodenum?","1st (superior, mostly intraperitoneal), 2nd (descending, ampulla), 3rd (horizontal, crosses between aorta and SMA), 4th (ascending).","Quatro partes do duodeno."],["e33zep12d","Which part of the duodenum receives the common bile duct?","2nd (descending) part.","Segunda parte."],["1fc3az6af","Where is the ligament of Treitz and its significance?","Suspensory ligament at the duodenojejunal junction; divides upper and lower GI bleeding.","Separa sangramento alto e baixo."],["i8xl4ivgl","Which salivary gland is most commonly the site of tumors?","Parotid gland (pleomorphic adenoma most common).","Parótida."],["o0ndnhiwv","Which nerve passes through the parotid gland?","Facial nerve (CN VII); at risk in parotid surgery.","Nervo facial."],["uw1ojo1oi","What is the innervation of parotid secretion?","Parasympathetic from CN IX (via otic ganglion and auriculotemporal nerve).","Nervo IX."],["8wu70k780","What is the innervation of submandibular and sublingual glands?","Parasympathetic from CN VII (chorda tympani via submandibular ganglion).","Nervo VII."],["lqt2l9as1","What is the arterial supply of the pancreas?","Splenic artery branches (body/tail), superior and inferior pancreaticoduodenal arteries (head).","Esplênica e pancreaticoduodenais."],["1o4kmm134","Where is the spleen located and what ribs overlie it?","Left upper quadrant, beneath ribs 9-11.","Hipocôndrio esquerdo, costelas 9 a 11."],["1wby7l21k","What is the clinical relevance of left lower rib fractures?","Risk of splenic rupture.","Risco de ruptura do baço."],["1n4acyk19","What is the arterial supply of the rectum?","Superior rectal (IMA), middle rectal (internal iliac), inferior rectal (internal pudendal).","Retais superior, média e inferior."],["1bq9o6wh7","Where is McBurney point?","One-third the distance from the anterior superior iliac spine to the umbilicus; site of maximal tenderness in appendicitis.","Ponto de McBurney."],["1t95ovtyx","Where is the appendix's base found on the cecum?","Where the three taeniae coli converge.","Onde as tênias convergem."],["ydn5voyfb","What are taeniae coli, haustra, and epiploic appendages?","Features of the colon: longitudinal muscle bands, sacculations, fat tags.","Características do cólon."],["9092ev1ok","Which parts of the colon are intraperitoneal?","Transverse and sigmoid colon (and cecum variably).","Transverso e sigmoide."],["zk8kqj14b","What is the arterial supply of the appendix?","Appendicular artery (from ileocolic artery, a branch of SMA).","Artéria apendicular."],["1kagv3uxl","What is the gastroesophageal junction's lower esophageal sphincter?","Physiological sphincter (not anatomical) at the GE junction; prevents reflux.","Esfíncter fisiológico."],["tb9o991an","What are the three physiological esophageal narrowings?","Upper esophageal sphincter (cricopharyngeus), crossing of left main bronchus and aortic arch, diaphragmatic hiatus (LES).","Três estreitamentos do esôfago."],["68gc5v11w","Which nerves provide parasympathetic innervation to the gut up to the splenic flexure?","Vagus nerve.","Nervo vago."],["4x9ofp17h","Which nerves provide parasympathetic innervation distal to the splenic flexure?","Pelvic splanchnic nerves (S2-S4).","Nervos esplâncnicos pélvicos."],["kllz0z1pz","Where is visceral pain from foregut structures referred?","Epigastric region.","Epigástrio."],["29jz1p907","Where is visceral pain from midgut structures referred?","Periumbilical region (e.g., early appendicitis).","Região periumbilical."],["1f8t0g61v","Where is visceral pain from hindgut structures referred?","Hypogastric (suprapubic) region.","Região suprapúbica."],["xmdgveozb","What causes referred right shoulder pain in gallbladder disease?","Irritation of the diaphragm via the phrenic nerve (C3-C5).","Irritação do frênico."],["1g6x0a5vq","What is Kehr sign?","Left shoulder pain from splenic rupture (diaphragmatic irritation).","Dor no ombro esquerdo por baço rompido."],["f9y8avu9v","What is the lymphatic drainage of the stomach to the left supraclavicular node called?","Virchow node (sign of gastric cancer metastasis).","Nódulo de Virchow."],["ottvzo15q","What is a Sister Mary Joseph nodule?","Periumbilical metastatic nodule from intra-abdominal malignancy (often gastric).","Nódulo umbilical metastático."],["14azp5wat","What is a Krukenberg tumor?","Metastasis of gastric signet ring cell carcinoma to the ovaries (bilateral).","Metástase gástrica no ovário."],["1113kwn1w","Where are Peyer patches located and what do they do?","Lamina propria and submucosa of the ileum; M cells sample antigens; B cells produce IgA.","Íleo; produzem IgA."],["9tax861vt","What is the role of M cells?","Take up antigens in Peyer patches and present them to immune cells.","Captam antígenos."],["jvs3cw1d6","What is the arterial supply of the liver?","Hepatic artery proper (25% of blood flow, 50% of O2) and portal vein (75% of blood flow).","Artéria hepática e veia porta."],["1j7mrsw12","What is the venous drainage of the liver?","Hepatic veins into the IVC.","Veias hepáticas para a cava."],["jhotwd1e5","What is Budd-Chiari syndrome?","Hepatic vein thrombosis causing congestive liver disease: hepatomegaly, ascites, abdominal pain; associated with hypercoagulable states, polycythemia vera, pregnancy, HCC.","Trombose das veias hepáticas."],["13q9ol1an","What is the venous drainage of the esophagus?","Upper: inferior thyroid veins. Middle: azygos. Lower: left gastric (portal) — site of varices.","Varizes vêm da gástrica esquerda."],["1fen3utte","What is the arterial supply of the esophagus?","Upper: inferior thyroid artery. Middle: bronchial and esophageal branches of aorta. Lower: left gastric artery.","Três fontes arteriais."],["1vj6o9b16","What are the boundaries of the inguinal canal?","Floor: inguinal ligament. Roof: internal oblique and transversus abdominis. Anterior: external oblique aponeurosis. Posterior: transversalis fascia.","Limites do canal inguinal."],["ew15r81f1","What passes through the inguinal canal in males and females?","Males: spermatic cord. Females: round ligament of the uterus. Both: ilioinguinal nerve.","Cordão espermático ou ligamento redondo."],["sq0rehtu9","Which nerve is at risk during inguinal hernia repair?","Ilioinguinal nerve (sensation to anterior scrotum/labia, medial thigh).","Nervo ilioinguinal."],["ui3bg8nv9","What is the gubernaculum's adult remnant in females?","Ovarian ligament and round ligament of the uterus.","Ligamentos ovariano e redondo."],["90izaz13p","Which abdominal muscle forms the inguinal ligament?","External oblique aponeurosis.","Oblíquo externo."],["alggip1wp","Which layer forms the deep inguinal ring?","Transversalis fascia.","Fáscia transversal."],["m8olto1y2","Which layer forms the superficial inguinal ring?","External oblique aponeurosis.","Aponeurose do oblíquo externo."],["hjc7sy18n","What is the location of the gallbladder fundus on the body surface?","Tip of the 9th costal cartilage at the midclavicular line (Murphy point).","Ponto de Murphy."],["1uj8itg57","What is a duodenal diverticulum?","Outpouching usually near the ampulla; usually asymptomatic.","Divertículo perto da papila."],["5dfo7jnu7","What is the main blood supply of the pancreatic head and duodenum?","Pancreaticoduodenal arcades from the gastroduodenal (celiac) and inferior pancreaticoduodenal (SMA) arteries.","Arcadas pancreaticoduodenais."],["11ptmlie5","What is the ampulla of Vater?","Junction of the common bile duct and pancreatic duct entering the 2nd part of the duodenum.","Encontro do colédoco e ducto pancreático."],["n65bn01bx","Which lymph nodes drain the pancreas head?","Pancreaticoduodenal nodes and celiac/superior mesenteric nodes.","Linfonodos pancreaticoduodenais."]]},{"name":"Pathology (Part 1)","cards":[["wusqd0fru","What are aphthous ulcers?","Common painful shallow round to oval ulcers with gray base and erythematous halo in the mouth; associated with stress, celiac disease, IBD, Behçet.","Aftas: úlceras orais rasas e dolorosas."],["11102kr1d","What is squamous cell carcinoma of the oral cavity associated with?","Tobacco, alcohol, HPV-16 (oropharynx); precursor lesions leukoplakia and erythroplakia.","Tabaco, álcool e HPV-16; precursoras leucoplasia e eritroplasia."],["1g52ux8j9","What is leukoplakia?","White plaque that cannot be scraped off; premalignant (risk of squamous cell carcinoma).","Placa branca que não sai ao raspar; pré-maligna."],["in3x171xa","What is erythroplakia?","Red velvety patch; higher risk of dysplasia and carcinoma than leukoplakia.","Mancha vermelha; risco maior de displasia."],["1jiaxhz1o","What is oral hairy leukoplakia?","Painless white plaque on the lateral tongue due to EBV in immunocompromised patients (HIV); not premalignant.","Placa branca na borda da língua por EBV em HIV; não é pré-maligna."],["17k9am013","How is oral candidiasis distinguished from leukoplakia?","Candida plaques can be scraped off; leukoplakia cannot.","Cândida sai ao raspar; leucoplasia não."],["h0jl7lprk","What is the most common salivary gland tumor?","Pleomorphic adenoma (benign mixed tumor): painless mobile mass of the parotid; recurs if incompletely excised.","Adenoma pleomórfico da parótida; recidiva se a ressecção for incompleta."],["lbruzc1m9","What is the second most common benign salivary gland tumor?","Warthin tumor (papillary cystadenoma lymphomatosum): benign, often bilateral, in smokers, with germinal centers.","Tumor de Warthin: benigno, bilateral, em fumantes."],["167ao1mdf","What is the most common malignant salivary gland tumor?","Mucoepidermoid carcinoma (mucinous and squamous components).","Carcinoma mucoepidermoide é o maligno mais comum."],["hraxkv1h1","Why may a parotid malignancy present with facial paralysis?","Invasion of the facial nerve (CN VII).","Paralisia facial indica invasão do nervo facial."],["2jq3pm1p0","What is sialolithiasis?","Stone formation in salivary ducts (submandibular most common); recurrent pain and swelling with meals.","Cálculo no ducto salivar; dor ao comer."],["1nobdec1j","What is sialadenitis?","Inflammation of salivary glands, often due to obstruction, infection (S. aureus, mumps), or autoimmune disease (Sjögren).","Inflamação da glândula salivar."],["n9iqwn1g2","What is achalasia?","Failure of LES relaxation due to degeneration of inhibitory neurons (NO, VIP) of the myenteric plexus.","Acalasia: o EEI não relaxa por perda de neurônios inibitórios."],["c5no7ascy","Clinical features of achalasia?","Progressive dysphagia to both solids and liquids (vs obstruction: solids first), regurgitation, chest pain.","Disfagia para sólidos e líquidos desde o início."],["80l7d11cv","Imaging and manometry findings in achalasia?","Bird's beak on barium swallow (dilated esophagus with tapered LES), high LES pressure, incomplete LES relaxation, absent peristalsis.","Bico de pássaro; EEI hipertônico e sem peristalse."],["742iixfmn","Which infection causes secondary achalasia?","Chagas disease (Trypanosoma cruzi).","Chagas causa acalasia secundária."],["15x22z3ce","What is pseudoachalasia?","Achalasia-like presentation from malignancy at the GE junction.","Câncer na junção esofagogástrica imitando acalasia."],["17lignysi","What is Boerhaave syndrome?","Transmural (full-thickness) esophageal rupture due to violent retching; pneumomediastinum, subcutaneous emphysema (Hamman crunch); surgical emergency.","Ruptura transmural do esôfago por vômitos; emergência."],["17qcyg114","What is Mallory-Weiss syndrome?","Partial-thickness mucosal lacerations at the GE junction from severe vomiting (alcoholics, bulimia); painless hematemesis.","Laceração da mucosa na JEG por vômitos; hematêmese."],["bjsvo711e","What is diffuse esophageal spasm?","Spontaneous nonperistaltic contractions of the esophagus; dysphagia and chest pain; corkscrew esophagus on barium swallow.","Espasmo esofágico difuso: esôfago em saca-rolhas."],["1dzxzikma","What is eosinophilic esophagitis?","Infiltration of eosinophils in the esophagus in atopic patients: dysphagia, food impaction, ring-like esophagus (feline esophagus), unresponsive to PPIs alone.","Esofagite eosinofílica em atópicos; esôfago em anéis."],["t2pl07105","What causes esophageal strictures?","Caustic ingestion (lye), acid reflux, radiation.","Estenose por cáusticos, refluxo ou radiação."],["nmo8r31u3","What is Plummer-Vinson syndrome?","Triad of dysphagia (esophageal webs), glossitis, iron deficiency anemia; increased risk of esophageal squamous cell carcinoma.","Disfagia, glossite e anemia ferropriva; risco de CEC."],["1ni09w41c","What is Zenker diverticulum?","False diverticulum of the pharynx through Killian triangle (between thyropharyngeal and cricopharyngeal parts of inferior constrictor): halitosis, dysphagia, regurgitation, aspiration, neck mass.","Divertículo falso no triângulo de Killian; halitose."],["xbhl5449d","Is Zenker diverticulum true or false?","False (pulsion) diverticulum: only mucosa and submucosa herniate.","Falso: só mucosa e submucosa herniam."],["pasi25jkp","What is scleroderma esophageal involvement?","Esophageal smooth muscle atrophy causes decreased LES pressure and distal esophageal dysmotility: GERD and dysphagia; part of CREST.","Esclerodermia: EEI frouxo e refluxo."],["1n1eeeuly","What causes GERD?","Transient LES relaxation or decreased LES tone; risk factors include obesity, hiatal hernia, pregnancy, smoking, alcohol, scleroderma.","Relaxamento transitório ou tônus baixo do EEI."],["k934idr43","Symptoms of GERD?","Heartburn, regurgitation, dysphagia; may cause chronic cough, hoarseness (laryngitis), asthma exacerbation, and adult-onset asthma.","Azia e regurgitação; tosse, rouquidão e asma."],["80edlq1ki","Complications of GERD?","Erosive esophagitis, strictures, Barrett esophagus.","Esofagite, estenose e Barrett."],["1f8hxpign","What is Barrett esophagus?","Specialized intestinal metaplasia: nonkeratinized stratified squamous epithelium replaced by intestinal epithelium (nonciliated columnar with goblet cells) in the distal esophagus due to chronic GERD.","Metaplasia intestinal com células caliciformes no esôfago distal."],["1i1tx5xg2","What is the major risk of Barrett esophagus?","Esophageal adenocarcinoma.","Risco de adenocarcinoma de esôfago."],["1dkikpd1e","What is the most common esophageal cancer worldwide?","Squamous cell carcinoma.","No mundo: carcinoma espinocelular."],["ewx0501y5","What is the most common esophageal cancer in the US?","Adenocarcinoma.","Nos EUA: adenocarcinoma."],["1f1htc51f","Where does esophageal squamous cell carcinoma typically arise?","Upper two-thirds of the esophagus.","CEC: dois terços superiores do esôfago."],["l0wxaoeey","Risk factors for esophageal squamous cell carcinoma?","Alcohol, hot liquids, caustic strictures, smoking, achalasia, nitrosamines, Plummer-Vinson syndrome.","Álcool, tabaco, bebidas quentes, acalasia."],["1j4o4k01x","Where does esophageal adenocarcinoma typically arise?","Lower one-third of the esophagus.","Adenocarcinoma: terço inferior."],["kemkg51xt","Risk factors for esophageal adenocarcinoma?","Chronic GERD, Barrett esophagus, obesity, tobacco.","DRGE, Barrett, obesidade e tabaco."],["fj8wbs1nn","Typical presentation of esophageal cancer?","Progressive dysphagia (solids then liquids), weight loss; poor prognosis.","Disfagia progressiva e emagrecimento."],["1h0aqgo1n","What are esophageal varices and their cause?","Dilated submucosal veins in the lower esophagus from portal hypertension (left gastric vein); risk of massive hematemesis.","Veias dilatadas por hipertensão portal; sangram muito."],["4599c4xs6","What is infectious esophagitis seen in immunocompromised patients?","Candida (white pseudomembranes), HSV-1 (punched-out ulcers), CMV (linear ulcers).","Cândida, HSV e CMV em imunossuprimidos."],["1vme1tfyb","What is pill esophagitis?","Esophageal injury from pills (bisphosphonates, tetracyclines, NSAIDs, potassium chloride, iron) lodged in the esophagus.","Lesão por comprimido parado no esôfago."],["18dls481w","What is acute gastritis?","Erosions from disruption of mucosal barrier: NSAIDs, burns (Curling ulcer), brain injury (Cushing ulcer), alcohol, chemotherapy, uremia, shock.","Erosões por AINEs, álcool, queimadura ou choque."],["10h7t7y18","What is a Curling ulcer?","Stress ulcer in severe burns due to hypovolemia and decreased mucosal blood flow.","Úlcera de estresse em grande queimado."],["l8rybv1s4","What is a Cushing ulcer?","Stress ulcer from brain injury due to increased vagal stimulation and gastric acid.","Úlcera de estresse após lesão cerebral."],["kvkfykcns","What is chronic gastritis type A (autoimmune)?","Autoantibodies to parietal cells or intrinsic factor in the fundus/body: pernicious anemia, achlorhydria, hypergastrinemia; associated with other autoimmune diseases.","Gastrite autoimune do corpo e fundo; anemia perniciosa."],["umo8ly1cv","What is chronic gastritis type B?","H. pylori infection, most commonly in the antrum; increased risk of peptic ulcer disease, gastric adenocarcinoma, MALT lymphoma.","Gastrite por H. pylori no antro."],["7t9sdo1x1","Mnemonic for chronic gastritis types?","A: Autoimmune, Antibodies, Achlorhydria, pernicious Anemia. B: Bacteria (H. pylori).","A = autoimune; B = bactéria."],["1pzotst1g","What is Ménétrier disease?","Hyperplasia of gastric mucosa with hypertrophied rugae (brain gyri), excess mucus, protein loss, parietal cell atrophy (decreased acid); precancerous.","Pregas gigantes, perda de proteína e pouco ácido."],["zcbiaz4y2","What is the most common type of gastric cancer?","Adenocarcinoma.","Adenocarcinoma."],["10bob7hq5","Risk factors for intestinal-type gastric adenocarcinoma?","H. pylori, dietary nitrosamines (smoked foods), tobacco, achlorhydria, chronic gastritis, type A blood.","H. pylori, nitrosaminas, tabaco, gastrite crônica."],["11d1a0rjr","Features of intestinal-type gastric cancer?","Ulcer with raised margins, usually on the lesser curvature.","Úlcera de bordas elevadas na pequena curvatura."],["1na0cy6zq","Features of diffuse-type gastric cancer?","Not associated with H. pylori; signet ring cells (mucin-filled), stomach wall thickening (linitis plastica); E-cadherin (CDH1) loss.","Células em anel de sinete; linite plástica."],["g29rwcp4w","What are signs of gastric cancer metastasis?","Virchow node, Krukenberg tumor (ovaries), Sister Mary Joseph nodule, Blumer shelf (rectal shelf), acanthosis nigricans, Leser-Trélat sign.","Virchow, Krukenberg, Irmã Maria José."],["ttwbp2wp2","What is the Leser-Trélat sign?","Sudden appearance of multiple seborrheic keratoses, a paraneoplastic sign of visceral malignancy (often GI adenocarcinoma).","Ceratoses seborreicas súbitas: sinal de câncer visceral."],["131s0vk1k","What is MALT lymphoma of the stomach associated with?","H. pylori; may regress with eradication.","Linfoma MALT ligado ao H. pylori."],["np0j2f1ss","What is a gastrointestinal stromal tumor?","Most common mesenchymal tumor of the GI tract (stomach most common), from interstitial cells of Cajal; c-KIT positive; treated with imatinib.","GIST: c-KIT positivo, tratado com imatinibe."],["nz66qs11a","Which ulcer type is associated with pain worse with meals?","Gastric ulcer (weight loss).","Úlcera gástrica: dor piora ao comer."],["fo5d411kj","Which ulcer type is associated with pain relieved by meals?","Duodenal ulcer (pain decreases with meals, weight gain).","Úlcera duodenal: dor melhora ao comer."],["7e4kigtpa","Most common cause of duodenal ulcers?","H. pylori (about 90%); also NSAIDs and Zollinger-Ellison syndrome.","H. pylori."],["1sxyiv1xq","Most common cause of gastric ulcers?","H. pylori (about 70%) and NSAIDs.","H. pylori e AINEs."],["1j9229m1r","Why should gastric ulcers be biopsied?","Risk of malignancy (especially with heaped margins); duodenal ulcers are generally benign.","Úlcera gástrica pode ser câncer."],["11gw7iowf","Complications of peptic ulcer disease?","Hemorrhage, perforation (free air under diaphragm, referred shoulder pain), obstruction.","Sangramento, perfuração e obstrução."],["puvo3sbl9","Which artery bleeds with a posterior wall duodenal ulcer?","Gastroduodenal artery.","Artéria gastroduodenal."],["41xnkty6n","What does free air under the diaphragm on upright x-ray indicate?","Perforated hollow viscus (e.g., perforated ulcer).","Perfuração de víscera oca."],["1b5n79buu","How is H. pylori diagnosed?","Urea breath test, stool antigen test, biopsy with histology/rapid urease test; serology cannot confirm eradication.","Teste respiratório, antígeno fecal ou biópsia."],["somig085e","Treatment of H. pylori?","Triple therapy (PPI + clarithromycin + amoxicillin or metronidazole) or bismuth quadruple therapy (PPI, bismuth, metronidazole, tetracycline).","IBP com antibióticos ou esquema quádruplo com bismuto."],["9lh40l1gu","What is Zollinger-Ellison syndrome's ulcer location clue?","Multiple ulcers, ulcers distal to the duodenum (jejunum), refractory to therapy.","Úlceras múltiplas, distais e refratárias."],["g41rrt13w","What is a dieulafoy lesion?","Large tortuous submucosal artery that erodes through the mucosa, causing massive GI bleeding (often in the stomach).","Artéria submucosa exposta; sangramento maciço."],["bd3hif1jr","What is gastric outlet obstruction's metabolic effect?","Hypokalemic hypochloremic metabolic alkalosis from vomiting.","Alcalose metabólica com hipocloremia e hipocalemia."],["5sgcc7wrw","What is hypertrophic pyloric stenosis's age group?","Infants 2-6 weeks old.","Lactentes de 2 a 6 semanas."],["1tht5fj1w","What is malabsorption's general presentation?","Diarrhea, steatorrhea, weight loss, weakness, vitamin and mineral deficiencies.","Diarreia, esteatorreia, emagrecimento e deficiências."],["nvn0xz1fl","What is celiac disease?","Autoimmune disorder from gluten (gliadin) sensitivity; HLA-DQ2 and DQ8; affects distal duodenum and proximal jejunum.","Doença celíaca: reação autoimune ao glúten."],["qprm1ivnr","Clinical features of celiac disease?","Malabsorption, diarrhea, steatorrhea, weight loss, bloating, iron deficiency anemia, osteoporosis; dermatitis herpetiformis.","Má absorção, anemia ferropriva, dermatite herpetiforme."],["17qtc2i1c","Serology for celiac disease?","IgA anti-tissue transglutaminase (tTG), anti-endomysial, anti-deamidated gliadin peptide; check total IgA (IgA deficiency is associated).","Anti-transglutaminase IgA; checar IgA total."],["1pc903u1b","Histology of celiac disease?","Villous atrophy, crypt hyperplasia, intraepithelial lymphocytosis.","Atrofia de vilosidades e hiperplasia de criptas."],["fiq0l19dp","What malignancy is increased in celiac disease?","Enteropathy-associated T-cell lymphoma (and small bowel adenocarcinoma).","Linfoma T associado a enteropatia."],["123xza119","What skin condition is associated with celiac disease?","Dermatitis herpetiformis (pruritic papulovesicles on extensor surfaces; IgA deposits in dermal papillae).","Dermatite herpetiforme."],["1cn95kl1h","What is tropical sprue?","Malabsorption in residents/visitors of tropical areas, likely infectious; affects entire small bowel; responds to antibiotics and folate.","Espru tropical: melhora com antibiótico e folato."],["94bebd1ed","What is Whipple disease?","Infection with Tropheryma whipplei (gram positive); PAS-positive foamy macrophages in intestinal lamina propria; malabsorption, arthralgias, cardiac and neurologic symptoms; often older men.","Doença de Whipple: macrófagos PAS positivos."],["1efasb91m","Mnemonic for Whipple disease features?","Foamy Whipped cream in a CAN: Cardiac, Arthralgias, Neurologic symptoms.","Coração, articulações e sistema nervoso."],["1q0uvgne3","What is lactose intolerance's histology?","Normal intestinal villi (in primary lactase deficiency).","Vilosidades normais."],["1lc0a9bgp","What is pancreatic insufficiency's effect on digestion?","Malabsorption of fat, fat-soluble vitamins, and B12; steatorrhea; decreased fecal elastase; normal D-xylose test.","Má absorção de gordura; D-xilose normal."],["17uwlhi8o","Causes of pancreatic insufficiency?","Chronic pancreatitis, cystic fibrosis, obstructing cancer.","Pancreatite crônica, fibrose cística, câncer."],["ozycr61hd","What is abetalipoproteinemia's intestinal finding?","Lipid accumulation within enterocytes.","Gordura acumulada nos enterócitos."],["s4qq3q14z","What is the classic cause of upper GI bleeding in alcoholics with vomiting?","Mallory-Weiss tear (also varices and peptic ulcers).","Laceração de Mallory-Weiss."],["5mv1hcmra","What is the classic finding of ischemic gastric fundus after splenic artery occlusion?","Infarction due to poor collaterals of short gastric arteries.","Artérias gástricas curtas sem colaterais."],["1y1ldvo1f","What is gastroparesis's most common cause?","Diabetes mellitus (autonomic neuropathy).","Diabetes (neuropatia autonômica)."],["2oc1071mt","What is linitis plastica?","Leather-bottle stomach from diffuse-type gastric adenocarcinoma infiltrating the wall.","Estômago em garrafa de couro."],["80cxis1in","What is hiatal hernia's main symptom?","GERD (sliding type).","Refluxo."],["cruhyv19k","What is the main concern with a paraesophageal hernia?","Strangulation (volvulus) of the herniated stomach.","Risco de estrangulamento."],["1se9ck42m","What is the Schatzki ring?","Lower esophageal mucosal ring causing intermittent solid food dysphagia (steakhouse syndrome).","Anel esofágico distal; engasgo com carne."],["v3npbya7t","What is the typical dysphagia in mechanical obstruction vs motility disorders?","Mechanical: solids first, progressing to liquids. Motility: solids and liquids from the start.","Mecânica: sólidos primeiro; motora: ambos."],["19e5s7nw5","What is oropharyngeal dysphagia?","Difficulty initiating swallowing (coughing, choking, nasal regurgitation); often neurologic (stroke, myasthenia, Parkinson).","Dificuldade de iniciar a deglutição; causa neurológica."],["1mm1rn31l","What is odynophagia?","Painful swallowing; suggests infection (Candida, HSV, CMV), pill esophagitis, or ulceration.","Dor ao engolir; infecção ou úlcera."],["8pif3ex14","What is esophageal atresia's prenatal sign?","Polyhydramnios.","Polidrâmnio."],["17xpy9wkz","What is caustic ingestion's long-term risk?","Esophageal strictures and squamous cell carcinoma.","Estenose e carcinoma espinocelular."],["1ah472110","What is the main cause of upper GI bleeding overall?","Peptic ulcer disease.","Úlcera péptica."],["zxbwro1r4","What is melena?","Black tarry stool from upper GI bleeding (digested blood).","Fezes pretas por sangramento alto."],["1hnx9e4dn","What is hematochezia?","Bright red blood per rectum, usually lower GI bleeding (or brisk upper GI bleed).","Sangue vivo pelo reto."],["85k83vfg0","What lab finding suggests upper GI bleeding?","Elevated BUN-to-creatinine ratio (digested blood protein absorption).","Ureia alta sugere sangramento alto."],["1bc5mifs2","What is the initial management of acute upper GI bleeding?","Resuscitation (two large-bore IVs, fluids, transfusion if needed), IV PPI, endoscopy; octreotide and antibiotics for suspected variceal bleeding.","Ressuscitação, IBP venoso e endoscopia."],["z1vymr1cg","What is atrophic gastritis's risk?","Gastric adenocarcinoma and carcinoid tumors (from hypergastrinemia-induced ECL cell hyperplasia).","Adenocarcinoma e carcinoide gástrico."],["lolg7p15p","What is intestinal metaplasia of the stomach?","Gastric epithelium replaced by intestinal-type epithelium (often from H. pylori); precursor to intestinal-type gastric cancer.","Precursora do câncer gástrico intestinal."],["1jb88xolo","What is gastric MALT lymphoma's treatment if early stage?","H. pylori eradication.","Erradicar o H. pylori."],["ff6oeihbm","What is a bezoar?","Mass of undigested material in the stomach (trichobezoar: hair; phytobezoar: plant fibers); risk with gastroparesis or prior surgery.","Massa não digerida no estômago."],["1qo7tynsq","What is hypertrophic gastropathy?","Giant rugal folds (Ménétrier disease or Zollinger-Ellison).","Pregas gigantes: Ménétrier ou gastrinoma."],["113iev51a","What does a gastrin level >1000 pg/mL with gastric pH <2 suggest?","Gastrinoma (Zollinger-Ellison syndrome).","Gastrinoma."],["17fno7e1c","What is the secretin stimulation test result in gastrinoma?","Paradoxical increase in gastrin (normally gastrin decreases).","A gastrina sobe paradoxalmente."],["1rcbtut1e","What is postgastrectomy syndrome's late hypoglycemia due to?","Rapid glucose absorption triggers excessive insulin release, followed by hypoglycemia.","Pico de insulina após absorção rápida."],["jogfm21rm","What is afferent loop syndrome?","Obstruction of the afferent limb after Billroth II gastrojejunostomy, causing postprandial pain and bilious vomiting.","Obstrução da alça aferente após Billroth II."],["1t5n6l3wz","What deficiencies occur after total gastrectomy?","B12 (no intrinsic factor), iron, folate, calcium, vitamin D.","Falta de B12, ferro, folato, cálcio e vitamina D."],["1npmg8l1j","What is sialadenosis?","Noninflammatory bilateral salivary gland enlargement associated with alcoholism, bulimia, diabetes, malnutrition.","Aumento não inflamatório das salivares."],["1ojl8zn3n","What is mumps parotitis?","Paramyxovirus infection causing bilateral parotid swelling; complications: orchitis, pancreatitis, aseptic meningitis; elevated serum amylase.","Caxumba: parotidite bilateral, risco de orquite."],["18lohcodt","What is the most common cause of a painful, swollen parotid gland in elderly dehydrated patients?","Acute bacterial parotitis (Staphylococcus aureus).","Parotidite por S. aureus."],["y6uik478u","What is Sjögren syndrome's effect on salivary glands?","Lymphocytic infiltration causing dry mouth (xerostomia), bilateral parotid enlargement; increased risk of B-cell lymphoma.","Boca seca; risco de linfoma B."],["34je5a9sw","What is the gastric location of most peptic ulcers?","Lesser curvature of the antrum.","Pequena curvatura do antro."],["zypj8f15r","What is esophageal manometry's role?","Diagnosing motility disorders (achalasia, diffuse esophageal spasm, scleroderma).","Diagnostica distúrbios motores."],["ltb6oh1ya","What is the treatment for achalasia?","Pneumatic dilation, surgical myotomy (Heller), peroral endoscopic myotomy, botulinum toxin injection; nitrates or CCBs as temporizing.","Dilatação, miotomia, POEM ou toxina botulínica."],["gfo5iu14n","What is the risk of malignancy in achalasia?","Increased risk of esophageal squamous cell carcinoma.","Risco de CEC."],["2omem4uj9","What is the most important risk factor for esophageal adenocarcinoma?","Barrett esophagus from chronic GERD.","Esôfago de Barrett."],["14dgfbmwu","What is the management of Barrett esophagus with high-grade dysplasia?","Endoscopic eradication therapy (radiofrequency ablation, endoscopic resection).","Erradicação endoscópica."],["jij231ph7","What is a common first sign of gastric cancer in many patients?","Weight loss and early satiety; often presents late.","Emagrecimento e saciedade precoce."],["1bj9mlx1o","What is the role of NSAIDs in duodenal vs gastric ulcers?","NSAIDs are a major cause of both, more often gastric ulcers.","Causam ambas, mais as gástricas."],["k07ow96cm","What is gastric volvulus's classic triad (Borchardt triad)?","Severe epigastric pain, retching without vomiting, inability to pass a nasogastric tube.","Dor, ânsia sem vômito e sonda que não passa."],["wiumfgarn","What is gastric antral vascular ectasia (watermelon stomach)?","Dilated vessels in the antrum causing chronic GI bleeding and iron deficiency; associated with cirrhosis and scleroderma.","Estômago em melancia: sangramento crônico."],["1g27ylrxv","What is the role of endoscopy in dyspepsia?","Indicated with alarm features (age >60, weight loss, dysphagia, bleeding, anemia, persistent vomiting).","Endoscopia se houver sinais de alarme."],["ebrhmdruk","What is functional dyspepsia?","Chronic upper abdominal symptoms without structural disease on evaluation.","Sintomas sem doença estrutural."],["1e0omke1c","What does dysphagia with weight loss in a smoker and heavy drinker suggest?","Esophageal squamous cell carcinoma.","CEC de esôfago."],["4n3ddxw84","What is the most common site of esophageal perforation after endoscopy?","Upper esophagus near the cricopharyngeus (iatrogenic perforation is the most common cause overall).","Esôfago superior, perto do cricofaríngeo."],["harljs1mx","What is the treatment of eosinophilic esophagitis?","Elimination diet, PPIs, topical (swallowed) corticosteroids, dupilumab.","Dieta, IBP, corticoide deglutido, dupilumabe."],["1bwh3jz1x","What is the classic barium swallow finding in esophageal cancer?","Irregular, apple-core-like narrowing (shouldering).","Estreitamento irregular em maçã mordida."],["4yk9jn1sz","What is the classic barium finding in eosinophilic esophagitis?","Multiple concentric rings (trachealization) and narrow caliber esophagus.","Anéis concêntricos."],["1g4bked1r","What is the significance of an esophageal web in the upper esophagus with iron deficiency?","Plummer-Vinson syndrome; risk of squamous cell carcinoma.","Síndrome de Plummer-Vinson."],["1fu94tc19","What is a common cause of acute hematemesis after binge drinking?","Mallory-Weiss tear.","Mallory-Weiss."],["hdfvgw69w","What is the classic presentation of gastric outlet obstruction from peptic ulcer?","Vomiting of undigested food, early satiety, succussion splash.","Vômito de comida não digerida."],["58bm6lzq9","What is the most common site of carcinoid tumors in the GI tract?","Small intestine (ileum) and appendix (appendix more common historically).","Íleo e apêndice."],["122pao71b","What is the effect of PPIs on gastrin levels?","Increase gastrin (loss of acid feedback inhibition).","IBP aumenta a gastrina."],["etlxta2na","What is reflux esophagitis histology?","Basal zone hyperplasia, elongated papillae, intraepithelial eosinophils and neutrophils.","Hiperplasia basal e eosinófilos."],["zaek1s20d","What cell type defines Barrett esophagus histologically?","Goblet cells (intestinal metaplasia).","Células caliciformes."]]},{"name":"Pathology (Part 2)","cards":[["1r6epbw1x","What is the most common cause of acute appendicitis in adults vs children?","Adults: fecalith obstruction. Children: lymphoid hyperplasia.","Adulto: fecalito; criança: hiperplasia linfoide."],["ra905s8db","Classic progression of pain in appendicitis?","Initial diffuse periumbilical pain (visceral), migrating to McBurney point (parietal peritoneum irritation).","Dor periumbilical que migra para a fossa ilíaca direita."],["5jd134nzb","Signs of appendicitis on exam?","McBurney point tenderness, Rovsing sign, psoas sign, obturator sign.","Sinais de McBurney, Rovsing, psoas e obturador."],["n3k87516d","What is Rovsing sign?","Pain in the right lower quadrant on palpation of the left lower quadrant.","Dor à direita ao palpar a esquerda."],["uwonumrtf","What is the psoas sign?","Right lower quadrant pain with extension of the right hip; suggests retrocecal appendicitis.","Dor ao estender o quadril direito; apêndice retrocecal."],["nmo7rq1wg","What is the obturator sign?","Pain with internal rotation of the flexed right hip; suggests pelvic appendix.","Dor à rotação interna do quadril; apêndice pélvico."],["iso6aawb5","Treatment of acute appendicitis?","Appendectomy (antibiotics alone in selected uncomplicated cases).","Apendicectomia."],["1hp3vq0mf","What is a diverticulum?","Blind pouch protruding from the alimentary tract that communicates with the lumen.","Bolsa cega que se comunica com a luz intestinal."],["19a7u87bn","True vs false diverticulum?","True: all gut wall layers (Meckel). False (pseudodiverticulum): only mucosa and submucosa outpouch (colonic diverticula).","Verdadeiro tem todas as camadas; falso só mucosa e submucosa."],["1omcdv1ym","Where do colonic diverticula usually form and why?","Sigmoid colon, at weak points where the vasa recta perforate the muscularis externa; high intraluminal pressure.","Sigmoide, onde os vasos retos atravessam a parede."],["6ubfu91g8","Risk factors for diverticulosis?","Low-fiber diet, older age, obesity, physical inactivity, constipation.","Pouca fibra, idade, obesidade, sedentarismo."],["1pxtnw61y","Clinical features of diverticulosis?","Often asymptomatic; most common cause of painless hematochezia in older adults.","Geralmente assintomática; causa comum de sangramento indolor."],["1kfj53afc","What is diverticulitis?","Inflammation of diverticula from obstruction and perforation: left lower quadrant pain, fever, leukocytosis.","Inflamação dos divertículos: dor na fossa ilíaca esquerda e febre."],["1lwy5lyxn","Complications of diverticulitis?","Abscess, fistula (colovesical: pneumaturia), obstruction, perforation and peritonitis.","Abscesso, fístula, obstrução e perfuração."],["3mplnxfi7","Imaging test of choice for suspected diverticulitis?","CT abdomen and pelvis with contrast; avoid colonoscopy acutely.","Tomografia; evitar colonoscopia na fase aguda."],["1uphb3614","What is a colovesical fistula's classic symptom?","Pneumaturia (air in urine) and fecaluria with recurrent UTIs.","Ar e fezes na urina."],["1wyrrw81w","What is Hirschsprung disease's typical presentation?","Newborn fails to pass meconium within 48 hours, distended abdomen, explosive stool on rectal exam.","Recém-nascido sem mecônio em 48 h."],["u8o63k1h0","What is intussusception?","Telescoping of a proximal bowel segment into a distal segment, most commonly ileocolic.","Invaginação de uma alça dentro da outra."],["pcko411bj","Clinical features of intussusception?","Intermittent abdominal pain (drawing legs up), vomiting, currant jelly stools, sausage-shaped mass; children under 2.","Dor intermitente, fezes em geleia de groselha, massa em salsicha."],["gvrwdg19q","What are lead points for intussusception?","Children: lymphoid hyperplasia (after viral infection, rotavirus vaccine), Meckel diverticulum, IgA vasculitis. Adults: tumors.","Criança: hiperplasia linfoide; adulto: tumor."],["1bt3ys4gn","Imaging and treatment of intussusception?","Ultrasound shows target sign; air or contrast enema is diagnostic and therapeutic.","Sinal do alvo; enema reduz."],["c4mufq1eu","What is volvulus?","Twisting of a portion of bowel around its mesentery, causing obstruction and infarction.","Torção da alça em torno do mesentério."],["hfgo0q1n3","Where does volvulus occur in infants vs elderly?","Infants and children: midgut. Elderly: sigmoid colon (coffee bean sign on x-ray).","Criança: intestino médio; idoso: sigmoide."],["hs4fj21vn","What is cecal volvulus?","Volvulus of the cecum, often in younger adults with a mobile cecum.","Torção do ceco em adultos mais jovens."],["idqqkk6lr","What is acute mesenteric ischemia?","Critical blockage of intestinal blood flow (often embolic from atrial fibrillation) causing small bowel infarction: pain out of proportion to exam.","Dor desproporcional ao exame por isquemia intestinal."],["1o34c1csm","What is chronic mesenteric ischemia?","Intestinal angina: atherosclerosis of celiac, SMA, or IMA causing postprandial epigastric pain and food aversion with weight loss.","Angina intestinal: dor após comer e emagrecimento."],["xxscu61oa","What is ischemic colitis?","Reduction in colonic blood flow causing ischemia; pain followed by bloody diarrhea; watershed areas (splenic flexure, rectosigmoid) in older adults.","Isquemia do cólon nas áreas de fronteira; dor e diarreia com sangue."],["1quxhrrnq","What is the thumbprinting sign?","Thickened bowel wall from submucosal edema/hemorrhage on imaging, seen in ischemic colitis.","Parede espessada em impressão digital; colite isquêmica."],["vd8t3g1k7","What is angiodysplasia?","Tortuous dilation of vessels causing hematochezia; most often cecum, terminal ileum, ascending colon; associated with ESRD, von Willebrand disease, aortic stenosis (Heyde syndrome).","Vasos dilatados no ceco; sangramento; ligada à estenose aórtica."],["1jbegh610","What is Heyde syndrome?","Aortic stenosis with GI bleeding from angiodysplasia (acquired von Willebrand deficiency).","Estenose aórtica com sangramento por angiodisplasia."],["1lzofe11e","What is small bowel obstruction's most common cause?","Adhesions from prior surgery; also hernias and tumors.","Aderências de cirurgia prévia."],["c7ark5lz9","Clinical features of small bowel obstruction?","Abrupt colicky pain, nausea, vomiting, distension, obstipation; dilated loops with air-fluid levels on x-ray.","Cólica, vômitos, distensão e níveis hidroaéreos."],["mdpva2vl5","What is a closed-loop obstruction?","Obstruction at two points (e.g., volvulus, hernia), high risk of strangulation; surgical emergency.","Obstrução em dois pontos; risco de estrangulamento."],["1sul67d3n","What is gallstone ileus?","Gallstone passes through a cholecystoenteric fistula and obstructs the ileocecal valve; pneumobilia on imaging.","Cálculo biliar obstrui a válvula ileocecal; ar nas vias biliares."],["1vt8jvw10","What is ileus?","Intestinal hypomotility without mechanical obstruction: after surgery, hypokalemia, opioids, sepsis; absent bowel sounds.","Hipomotilidade sem obstrução mecânica."],["cs3nt41hx","What is Ogilvie syndrome?","Acute colonic pseudo-obstruction: massive colonic dilation without mechanical cause, in hospitalized patients; treated with neostigmine or decompression.","Pseudo-obstrução aguda do cólon; neostigmina."],["rn5yd3t21","What is meconium ileus?","Meconium plug obstructs the intestine, preventing stool passage at birth; associated with cystic fibrosis.","Rolha de mecônio; ligada à fibrose cística."],["rrp0bc1nx","What is necrotizing enterocolitis?","Necrosis of intestinal mucosa (often terminal ileum, colon) in premature formula-fed infants; pneumatosis intestinalis, portal venous gas.","Necrose intestinal em prematuros; gás na parede."],["12xlh081d","What is the main histologic difference between Crohn disease and ulcerative colitis?","Crohn: transmural inflammation with noncaseating granulomas. UC: mucosal and submucosal inflammation, crypt abscesses.","Crohn é transmural com granulomas; RCU é mucosa."],["hqdr5f1nz","What is the location of Crohn disease?","Any portion of the GI tract, most often terminal ileum and colon; rectal sparing; skip lesions.","Qualquer parte do TGI, lesões salteadas, poupa o reto."],["1s4qz7mw9","What is the location of ulcerative colitis?","Colon, always involving the rectum, continuous proximal extension.","Cólon contínuo a partir do reto."],["x0ly9z88f","Gross morphology of Crohn disease?","Transmural inflammation, fistulas, cobblestone mucosa, creeping fat, bowel wall thickening (string sign), linear ulcers, fissures.","Mucosa em paralelepípedo, fístulas, gordura migratória."],["239cza1ai","Gross morphology of ulcerative colitis?","Friable mucosa with superficial ulcers and pseudopolyps; loss of haustra (lead pipe appearance).","Mucosa friável, pseudopólipos, cólon em cano de chumbo."],["f94uym12u","Complications of Crohn disease?","Malabsorption, B12 deficiency, calcium oxalate stones, gallstones, fistulas, strictures, perianal disease, colorectal cancer if colitis.","Má absorção, cálculos, fístulas, estenoses."],["1jo8khbg7","Complications of ulcerative colitis?","Malnutrition, sclerosing cholangitis, toxic megacolon, colorectal carcinoma (worse with right-sided colitis or PSC).","Colangite esclerosante, megacólon tóxico, câncer."],["1dtfbapww","Intestinal manifestation of UC vs Crohn diarrhea?","UC: bloody diarrhea. Crohn: diarrhea that may or may not be bloody.","RCU sangra mais."],["5195ss1su","Extraintestinal manifestations of IBD?","Erythema nodosum, pyoderma gangrenosum, uveitis, episcleritis, migratory polyarthritis, ankylosing spondylitis, aphthous ulcers, kidney stones.","Eritema nodoso, pioderma, uveíte, artrite."],["2kc5ksgky","Which IBD is associated with primary sclerosing cholangitis?","Ulcerative colitis (p-ANCA positive).","Retocolite ulcerativa."],["ugcgs9r6z","How does smoking affect Crohn disease vs UC?","Smoking worsens Crohn disease and is protective in UC.","Fumo piora Crohn e protege na RCU."],["19avfe1yf","Treatment options for IBD?","5-ASA (UC), corticosteroids, azathioprine, anti-TNF (infliximab, adalimumab), vedolizumab, ustekinumab; colectomy cures UC.","Aminossalicilatos, corticoide, imunossupressores e biológicos."],["ab0idoho0","What is toxic megacolon?","Acute colonic dilation with systemic toxicity, complication of UC or C. difficile; risk of perforation.","Dilatação aguda do cólon com toxicidade."],["tj792q6w8","What is microscopic colitis?","Chronic watery diarrhea in older women with normal colonoscopy; biopsy shows lymphocytic or collagenous colitis.","Diarreia aquosa com colonoscopia normal."],["1mdbi9egp","What is irritable bowel syndrome?","Recurrent abdominal pain associated with change in stool frequency or form, ≥1 day/week for 3 months; no structural disease.","Dor abdominal recorrente com alteração do hábito intestinal."],["6g30jb1xu","Risk factors and associations of IBS?","Female sex, middle age, fibromyalgia, depression, anxiety.","Mulheres, ansiedade, depressão, fibromialgia."],["1p2rd1ry9","Treatment of IBS?","Symptomatic: fiber, antispasmodics, laxatives or antidiarrheals, TCAs, SSRIs.","Tratamento sintomático."],["8slusz6pq","What are colonic polyps?","Growths of tissue within the colon; may be neoplastic or non-neoplastic.","Crescimentos de tecido no cólon."],["46vnux1oj","What are hyperplastic polyps?","Non-neoplastic, most common nonneoplastic polyp, usually small in the rectosigmoid; serrated (sawtooth) architecture.","Pólipo hiperplásico: não neoplásico, comum no retossigmoide."],["1emfklulg","What are hamartomatous polyps?","Generally benign; juvenile polyps and Peutz-Jeghers polyps.","Pólipos hamartomatosos, em geral benignos."],["185eaml16","What are juvenile polyps?","Sporadic hamartomatous polyps in children <5 years, typically rectal; may cause rectal bleeding or prolapse.","Pólipo juvenil retal em crianças."],["1gdxf8h1b","What is juvenile polyposis syndrome?","Autosomal dominant: multiple juvenile polyps; increased colorectal cancer risk.","Muitos pólipos juvenis; risco de câncer."],["1lr3l27he","What are adenomatous polyps?","Neoplastic polyps via chromosomal instability (APC, KRAS); tubular (less malignant), tubulovillous, villous (more malignant).","Adenomas: neoplásicos; vilosos são os mais perigosos."],["czcd7p62e","What increases the malignant potential of adenomatous polyps?","Size >1 cm, villous histology, high-grade dysplasia.","Tamanho >1 cm, histologia vilosa, displasia de alto grau."],["a8uat71e0","What are sessile serrated polyps?","Premalignant polyps via CpG island methylator phenotype (BRAF mutation, microsatellite instability); often right-sided; saw-tooth crypts.","Pólipos serrilhados: via de metilação, BRAF, lado direito."],["7f5j6jmbh","What is the adenoma-carcinoma sequence?","APC loss (polyp formation), KRAS mutation (adenoma growth), TP53 loss (carcinoma).","APC, KRAS e depois TP53."],["1c4iu6q16","What is the microsatellite instability pathway?","Mismatch repair gene mutations (Lynch syndrome or sporadic MLH1 methylation) causing right-sided cancers.","Defeito no reparo de mau pareamento; tumores à direita."],["13t04h21y","Risk factors for colorectal cancer?","Age, adenomatous/serrated polyps, family history, FAP, Lynch, IBD, tobacco, diet high in processed meat and low in fiber.","Idade, pólipos, família, DII, tabaco, dieta."],["ux2wdkfe4","When does average-risk colorectal cancer screening start?","Age 45 (colonoscopy every 10 years or stool-based tests).","A partir dos 45 anos."],["ek03w1tjs","Presentation of right-sided (ascending) colon cancer?","Exophytic mass, iron deficiency anemia, weight loss.","Direita: anemia ferropriva e massa."],["kw2olz1de","Presentation of left-sided (descending/sigmoid) colon cancer?","Infiltrating napkin-ring mass, change in bowel habits, obstruction, hematochezia; apple core lesion on barium enema.","Esquerda: obstrução e alteração do hábito; maçã mordida."],["1ofm4czfg","What tumor marker is used to monitor colorectal cancer?","CEA (carcinoembryonic antigen); not useful for screening.","CEA para seguimento, não rastreio."],["s3t3gxplq","Which infections are associated with colorectal cancer?","Streptococcus gallolyticus (bovis) bacteremia/endocarditis.","Bacteremia por S. gallolyticus."],["1pqub4tra","What is familial adenomatous polyposis's treatment?","Prophylactic colectomy (nearly 100% cancer risk).","Colectomia profilática."],["1ndt10v1k","What is Lynch syndrome's colonoscopy screening?","Colonoscopy every 1-2 years starting at 20-25 years.","Colonoscopia a cada 1-2 anos desde os 20-25."],["1w34tignw","What is the most common cause of lower GI bleeding in adults?","Diverticulosis.","Diverticulose."],["d5xuiovdz","What is the most common cause of lower GI bleeding in children?","Meckel diverticulum (also juvenile polyps, intussusception).","Divertículo de Meckel."],["1o94j93iv","What are internal hemorrhoids?","Dilated vascular cushions above the pectinate line; painless bleeding; can prolapse.","Hemorroida interna: indolor, sangra."],["3z0a0dzsr","What are external hemorrhoids?","Below the pectinate line; painful when thrombosed.","Hemorroida externa: dói quando trombosa."],["1wv9mhjc6","What is an anal fistula?","Abnormal connection between anal canal and perianal skin, usually from an anorectal abscess; associated with Crohn disease.","Trajeto entre canal anal e pele; associado a Crohn."],["10dyveq1u","What is anal cancer associated with?","HPV-16 and 18, HIV, receptive anal intercourse; squamous cell carcinoma below pectinate line.","HPV e HIV; carcinoma espinocelular."],["1j2eyee11","What is pseudomembranous colitis?","Colitis from Clostridioides difficile toxins A and B after antibiotics (clindamycin, fluoroquinolones, cephalosporins, PPIs).","Colite por C. difficile após antibióticos."],["1utjec215","Diagnosis and treatment of C. difficile colitis?","PCR or toxin detection in stool; oral vancomycin or fidaxomicin; fecal transplant for recurrence.","Toxina nas fezes; vancomicina oral ou fidaxomicina."],["nbm7kj131","What is the classic stool finding in shigellosis vs cholera?","Shigella: bloody, mucoid stools with fever. Cholera: rice-water stools.","Shigella: fezes com sangue; cólera: água de arroz."],["ca0x44ubj","Which organisms cause bloody diarrhea?","Campylobacter, E. histolytica, EHEC (O157:H7), EIEC, Salmonella, Shigella, Yersinia, C. difficile.","Campylobacter, Shigella, Salmonella, EHEC, amebas."],["1c40g1n13","Which organisms cause watery diarrhea?","ETEC, Vibrio cholerae, viruses (norovirus, rotavirus), Giardia, Cryptosporidium, C. perfringens.","ETEC, cólera, vírus, Giardia."],["1qosfwh1h","What causes hemolytic uremic syndrome after bloody diarrhea?","Shiga-like toxin from EHEC (O157:H7) or Shiga toxin from Shigella dysenteriae.","Toxina Shiga da E. coli O157:H7."],["3vpump1cl","What is carcinoid tumor of the small intestine?","Neuroendocrine tumor most common in the ileum; may cause carcinoid syndrome when metastatic to liver.","Tumor neuroendócrino no íleo."],["v93fb6t1g","What is the most common small bowel malignancy?","Neuroendocrine (carcinoid) tumor (adenocarcinoma is also common, more often in duodenum).","Tumor neuroendócrino."],["gldvbzug8","What is the classic triad of mesenteric ischemia risk?","Atrial fibrillation (emboli), atherosclerosis, hypercoagulable states.","Fibrilação atrial, aterosclerose, trombofilia."],["odx89p1c8","Initial lab clue in acute mesenteric ischemia?","Elevated lactate and leukocytosis; metabolic acidosis.","Lactato alto e acidose."],["1k1j5a21e","What is the most common site of Meckel diverticulum complications?","Bleeding from ectopic gastric mucosa ulcerating adjacent ileum.","Sangramento pela mucosa gástrica ectópica."],["137ua4e1x","What is short bowel syndrome?","Malabsorption after extensive small bowel resection: diarrhea, steatorrhea, nutritional deficiencies.","Má absorção após ressecção extensa."],["2xy08v12f","What is protein-losing enteropathy?","Excessive protein loss through the gut (e.g., Ménétrier, lymphangiectasia, IBD); hypoalbuminemia with edema.","Perda de proteínas pelo intestino."],["kz8exk4mw","What is intestinal lymphangiectasia?","Dilated lacteals causing protein-losing enteropathy, lymphopenia, and fat malabsorption.","Linfáticos dilatados; perda de proteína."],["hks53h10y","What is the target sign on ultrasound?","Concentric rings of bowel wall in intussusception.","Anéis concêntricos na intussuscepção."],["1b71r7oun","What is the coffee bean sign?","Sigmoid volvulus on abdominal x-ray.","Volvo de sigmoide."],["194j67ldp","What is the apple core lesion on barium enema?","Annular colorectal carcinoma narrowing the lumen.","Câncer colorretal anular."],["xzef0j1mu","What is a string sign on barium study?","Narrowed terminal ileum from Crohn disease (fibrosis/stricture).","Íleo estreitado na doença de Crohn."],["ovt0o71s0","What is the bird's beak sign on barium enema?","Sigmoid volvulus (and achalasia on esophagram).","Volvo de sigmoide; também acalasia."],["1c1gu7m19","What is the lead pipe colon?","Loss of haustra in chronic ulcerative colitis.","Perda das haustrações na RCU."],["1r4t2sb1h","What is pneumatosis intestinalis?","Gas in the bowel wall, classic in necrotizing enterocolitis.","Gás na parede intestinal."],["bnjfvm1kt","What causes cobblestone mucosa?","Crohn disease (linear ulcers separating edematous mucosa).","Doença de Crohn."],["xiverucsz","What are crypt abscesses?","Neutrophils within crypts, characteristic of ulcerative colitis.","Neutrófilos nas criptas; RCU."],["4a1gdz1u7","What lab suggests IBD activity vs IBS?","Fecal calprotectin elevated in IBD, normal in IBS.","Calprotectina fecal alta na DII."],["bsbsmonmh","What is the indication for colorectal cancer surveillance in UC?","Colonoscopy starting 8 years after diagnosis, every 1-3 years.","Colonoscopia 8 anos após o diagnóstico."],["1jmasnh1k","What causes fecal incontinence after obstetric trauma?","Damage to the anal sphincter or pudendal nerve.","Lesão do esfíncter anal ou nervo pudendo."],["1n2az35i5","What is rectal prolapse?","Protrusion of rectal wall through the anus; associated with chronic straining, cystic fibrosis in children, pelvic floor weakness.","Prolapso do reto; esforço crônico, fibrose cística."],["1mkkuw1ax","What is solitary rectal ulcer syndrome?","Rectal ulcer from chronic straining and mucosal prolapse; bleeding and mucus.","Úlcera retal por esforço crônico."],["2facpk533","What is Peutz-Jeghers syndrome?","Autosomal dominant (STK11): hamartomatous GI polyps and mucocutaneous hyperpigmentation; increased cancer risk.","Pólipos hamartomatosos e manchas nos lábios."],["z26xn8bow","What is Cowden syndrome's GI finding?","Hamartomatous polyps (PTEN mutation).","Pólipos hamartomatosos por PTEN."],["uduhc6xe1","What is Gardner syndrome's extraintestinal finding?","Osteomas, desmoid tumors, epidermoid cysts, dental abnormalities.","Osteomas, tumores desmoides, alterações dentárias."],["zw7d9w1e2","What is Turcot syndrome?","Polyposis (FAP or Lynch) plus brain tumors.","Polipose com tumor cerebral."],["19v2b0m1m","What does sigmoid volvulus usually affect demographically?","Elderly, institutionalized, chronically constipated patients.","Idosos acamados e constipados."],["hnpuo919h","Treatment of sigmoid volvulus without peritonitis?","Endoscopic decompression, followed by elective sigmoid resection.","Descompressão endoscópica e depois ressecção."],["qcmryu1fp","What is the leading cause of bowel obstruction in patients without prior surgery?","Hernias (incarcerated) and tumors.","Hérnias e tumores."],["xlnyoa1wd","What is the treatment of uncomplicated diverticulitis?","Bowel rest and, in selected patients, antibiotics; later colonoscopy to exclude cancer.","Repouso intestinal e antibiótico se necessário."],["1hzmzu81w","What is the treatment of diverticular abscess?","Percutaneous drainage and antibiotics.","Drenagem percutânea e antibiótico."],["1sor28r1b","What is the cause of most lower GI bleeding that stops spontaneously?","Diverticular bleeding.","Sangramento diverticular."],["xkmhr4yx2","What is the most common site of colon cancer?","Rectosigmoid colon.","Retossigmoide."],["6tp06910k","Which colon cancer pathway is associated with BRAF mutations and serrated polyps?","CpG island methylator phenotype (CIMP) pathway.","Via de metilação CIMP."],["iqnly917b","Why is right-sided colon cancer often detected late?","Large lumen and liquid stool allow growth without obstruction.","Luz ampla e fezes líquidas não obstruem."],["ufyz3hv7l","What is the role of aspirin in colorectal cancer?","Long-term use reduces colorectal cancer risk (COX-2 overexpression in tumors).","Uso prolongado reduz o risco."],["xyhhwes2m","Which drug class is used for metastatic colorectal cancer with wild-type KRAS?","EGFR inhibitors (cetuximab, panitumumab).","Anti-EGFR se KRAS selvagem."],["1py9g3e11","What is diversion colitis?","Inflammation in a defunctionalized colon segment after fecal diversion (lack of short-chain fatty acids).","Colite no segmento sem trânsito fecal."],["1n2dubq12","What is radiation enteritis or proctitis?","Inflammation after pelvic radiation: diarrhea, bleeding, strictures.","Inflamação após radioterapia pélvica."],["x2hqurs18","What is typhlitis (neutropenic enterocolitis)?","Inflammation of the cecum in neutropenic patients (chemotherapy).","Inflamação do ceco em neutropênicos."],["a1id4y1qo","What is the gold standard to diagnose celiac disease?","Small bowel (duodenal) biopsy on a gluten-containing diet.","Biópsia duodenal com dieta com glúten."],["1jjnpei1v","What is refractory celiac disease's malignant risk?","Enteropathy-associated T-cell lymphoma.","Linfoma T de enteropatia."],["1fx9zyl1w","What is the classic finding in giardiasis?","Foul-smelling fatty diarrhea after drinking from streams or camping; trophozoites or cysts in stool.","Diarreia gordurosa e fétida após água de rio."],["1p7tpgr17","What is the classic finding in amebic dysentery?","Bloody diarrhea with flask-shaped ulcers; may cause liver abscess (anchovy paste).","Úlceras em frasco; abscesso hepático."],["idyr021m6","What is traveler's diarrhea most commonly caused by?","Enterotoxigenic E. coli (ETEC).","E. coli enterotoxigênica."],["1ktwvq21w","What is the classic cause of diarrhea after fried rice?","Bacillus cereus (emetic toxin).","Bacillus cereus."],["ha302z1i8","What is the classic cause of diarrhea after undercooked poultry associated with Guillain-Barré?","Campylobacter jejuni.","Campylobacter jejuni."],["2mmw9we12","What is the classic cause of pseudoappendicitis?","Yersinia enterocolitica (mesenteric adenitis), often from pork or unpasteurized milk.","Yersinia: imita apendicite."],["2nhw7a1w3","What is the classic cause of diarrhea with rose spots and bradycardia?","Salmonella Typhi (typhoid fever).","Febre tifoide."],["1la5mdq1b","What is the treatment of most acute infectious diarrhea?","Oral rehydration; antibiotics for selected cases (avoid in EHEC due to HUS risk).","Reidratação oral."],["c1ds621c8","What is the role of loperamide in infectious diarrhea?","Avoid in bloody diarrhea or fever (risk of toxic megacolon).","Evitar se houver sangue ou febre."],["1hvqoi5gg","What is fecal impaction?","Hard immobile stool mass in the rectum, often in elderly or bedridden; may cause overflow diarrhea.","Fecaloma; pode causar diarreia paradoxal."],["yn9tg1jul","What drug class commonly causes constipation?","Opioids (also anticholinergics, CCBs like verapamil, iron, aluminum antacids).","Opioides."],["o489ti1ky","What is the mechanism of opioid-induced constipation treatment with methylnaltrexone?","Peripheral mu-opioid antagonist that does not cross the blood-brain barrier.","Antagonista opioide periférico."],["b1qknv1ku","What is pruritus ani's most common cause in children?","Pinworms (Enterobius vermicularis); tape test.","Oxiúros; teste da fita."],["18fn1u4ow","What is diverticular disease's prevention?","High-fiber diet.","Dieta rica em fibras."],["137gbuw15","What is the primary difference in colonic involvement between Crohn colitis and UC on endoscopy?","Crohn: patchy with skip lesions and aphthous ulcers. UC: continuous from the rectum.","Crohn salteado; RCU contínuo."],["1349smw1s","Which IBD more commonly causes perianal fistulas?","Crohn disease.","Crohn."],["5vw241fgz","Which IBD more commonly causes toxic megacolon?","Ulcerative colitis.","Retocolite ulcerativa."],["1vsnqexza","Which antibody is associated with Crohn disease?","ASCA (anti-Saccharomyces cerevisiae antibodies).","Anticorpo ASCA."],["1ei3y6g1k","Which antibody is associated with ulcerative colitis?","p-ANCA.","p-ANCA."],["1phos0r1i","Which vitamin deficiency is common after ileal Crohn disease or resection?","Vitamin B12.","Vitamina B12."],["15aoxiw1r","What is the classic infant presentation of malrotation with volvulus?","Bilious vomiting in the first weeks of life; surgical emergency.","Vômito bilioso no recém-nascido; emergência."],["ypqwh715w","What is the double bubble sign?","Duodenal atresia (dilated stomach and proximal duodenum), associated with Down syndrome.","Atresia duodenal; Down."],["12gu6gj1j","What is the classic GI defect associated with Down syndrome besides duodenal atresia?","Hirschsprung disease (and annular pancreas, imperforate anus).","Doença de Hirschsprung."]]},{"name":"Pathology (Part 3)","cards":[["acx9m61xk","What is cirrhosis?","Diffuse bridging fibrosis (via stellate cells) and regenerative nodules disrupting normal liver architecture.","Fibrose difusa com nódulos de regeneração."],["92t6aw1kx","Common causes of cirrhosis?","Alcohol, chronic viral hepatitis (B, C), NAFLD/MASLD, autoimmune, biliary disease, genetic/metabolic (hemochromatosis, Wilson, A1AT).","Álcool, hepatites virais, esteatose, doenças genéticas."],["s4sakx1qs","Effects of portal hypertension?","Esophageal varices, hematemesis, caput medusae, ascites, splenomegaly, anorectal varices, spontaneous bacterial peritonitis, hepatorenal syndrome.","Varizes, ascite, esplenomegalia, cabeça de medusa."],["18l8ned1v","Effects of liver cell failure?","Coma, scleral icterus, fetor hepaticus, spider angiomas, gynecomastia, jaundice, palmar erythema, testicular atrophy, coagulopathy, asterixis, hepatic encephalopathy.","Icterícia, encefalopatia, coagulopatia, aranhas vasculares."],["wx28ufsuf","What is the serum-ascites albumin gradient (SAAG) used for?","SAAG ≥1.1 g/dL indicates portal hypertension (cirrhosis, heart failure, Budd-Chiari); <1.1 suggests peritoneal causes (cancer, TB, nephrotic).","SAAG ≥1,1 indica hipertensão portal."],["1r8vadgex","What is spontaneous bacterial peritonitis?","Infection of ascitic fluid without an obvious source; ascitic PMN ≥250 cells/mm³; often E. coli or Klebsiella.","Infecção da ascite com ≥250 neutrófilos."],["19d8wu1dg","Treatment of spontaneous bacterial peritonitis?","Third-generation cephalosporin (e.g., ceftriaxone, cefotaxime) plus albumin.","Cefalosporina de 3ª geração e albumina."],["lv9k7g1pj","What is hepatorenal syndrome?","Rapidly progressive renal failure in cirrhosis due to splanchnic vasodilation and renal vasoconstriction; kidneys are histologically normal.","Insuficiência renal funcional na cirrose."],["1vgythzdg","What is hepatopulmonary syndrome?","Intrapulmonary vascular dilation in liver disease causing hypoxemia; platypnea and orthodeoxia.","Vasodilatação pulmonar e hipoxemia na cirrose."],["1psjv3fuc","What is hepatic encephalopathy?","Reversible neuropsychiatric dysfunction from ammonia and toxins in liver failure; asterixis, confusion, coma.","Confusão e asterixe por amônia."],["1farkd551","Triggers of hepatic encephalopathy?","Increased NH3 production (GI bleed, dietary protein, constipation, infection) or decreased removal (renal failure, diuretics, TIPS).","Sangramento, infecção, constipação, diuréticos."],["5mhpkmx4u","Treatment of hepatic encephalopathy?","Lactulose (traps NH4+ in gut) and rifaximin (reduces ammonia-producing bacteria).","Lactulose e rifaximina."],["v2qpspmv3","What is alcoholic hepatic steatosis?","Macrovesicular fatty change; reversible with alcohol cessation.","Esteatose alcoólica, reversível."],["oigq2tgnf","What is alcoholic hepatitis?","Swollen necrotic hepatocytes with neutrophil infiltration and Mallory-Denk bodies; AST:ALT >2:1, jaundice, fever.","Hepatite alcoólica: AST/ALT >2 e corpúsculos de Mallory."],["9tqve91fw","What are Mallory-Denk bodies?","Intracytoplasmic eosinophilic inclusions of damaged keratin filaments in hepatocytes (alcoholic hepatitis, NASH, Wilson).","Inclusões de queratina nos hepatócitos."],["6icidqjcr","What is alcoholic cirrhosis?","Final, irreversible stage: micronodular, shrunken liver with sclerosis around central vein (zone III).","Cirrose micronodular irreversível."],["wttx0llt7","What is nonalcoholic fatty liver disease (MASLD)?","Metabolic syndrome-associated fatty infiltration of hepatocytes; ALT > AST; may progress to steatohepatitis, cirrhosis, HCC.","Esteatose metabólica; ALT > AST."],["1ls6ewh1p","What is the most common cause of chronic liver disease in the US?","Nonalcoholic fatty liver disease (MASLD).","Doença hepática gordurosa metabólica."],["yzbxl1opp","What is the most common primary malignant liver tumor in adults?","Hepatocellular carcinoma.","Carcinoma hepatocelular."],["1ungxds9y","Risk factors for hepatocellular carcinoma?","HBV (even without cirrhosis), HCV, alcohol, NAFLD, hemochromatosis, A1AT deficiency, Wilson, aflatoxin (Aspergillus).","Hepatite B e C, álcool, aflatoxina, cirrose."],["124h5nbsb","Findings in hepatocellular carcinoma?","Anorexia, jaundice, tender hepatomegaly, increased AFP; may cause Budd-Chiari; spreads hematogenously.","AFP alta, hepatomegalia, icterícia."],["1rq621y85","How is HCC diagnosed in a cirrhotic patient?","Characteristic imaging (arterial enhancement with venous washout on CT/MRI), often without biopsy.","Imagem típica com realce arterial e lavagem."],["t9269310w","What is the most common benign liver tumor?","Cavernous hemangioma (biopsy contraindicated due to bleeding risk).","Hemangioma; não biopsiar."],["59oiqt193","What is hepatic adenoma?","Benign tumor associated with oral contraceptives and anabolic steroids; may regress with cessation; risk of rupture and hemorrhage.","Adenoma ligado a anticoncepcional; risco de ruptura."],["1gmgqia15","What is focal nodular hyperplasia?","Benign hepatocyte hyperplasia with a central stellate scar; no malignant potential.","Hiperplasia nodular focal com cicatriz central."],["13i44iq1u","What is angiosarcoma of the liver associated with?","Vinyl chloride, arsenic, Thorotrast exposure.","Cloreto de vinila e arsênico."],["1sv2gyt1t","What are the most common malignant liver tumors overall?","Metastases (GI, breast, lung).","Metástases."],["17p2ei51y","How is Budd-Chiari syndrome distinguished from right heart failure clinically?","Budd-Chiari has hepatomegaly and ascites without JVD or hepatojugular reflux.","Sem turgência jugular, ao contrário da insuficiência cardíaca."],["yl67g1jsr","What is alpha-1 antitrypsin deficiency's liver pathology?","Misfolded protein (PiZZ) accumulates in hepatocyte ER as PAS-positive globules, causing cirrhosis; emphysema in lungs.","Glóbulos PAS+ no fígado; cirrose e enfisema."],["1f98z81g6","What is the classic lung finding in alpha-1 antitrypsin deficiency?","Panacinar emphysema in lower lobes.","Enfisema panacinar de bases."],["18cuw3816","What is Reye syndrome?","Rare often fatal childhood hepatic encephalopathy after viral infection (VZV, influenza) treated with aspirin; mitochondrial abnormalities, microvesicular fatty liver.","Aspirina em criança com virose: fígado gorduroso e encefalopatia."],["1bzjms816","Why is aspirin avoided in children?","Risk of Reye syndrome (except Kawasaki disease).","Risco de síndrome de Reye."],["1f9n1qo71","What is unconjugated (indirect) hyperbilirubinemia caused by?","Hemolysis, physiologic newborn jaundice, Crigler-Najjar, Gilbert syndrome.","Hemólise, icterícia neonatal, Gilbert."],["1jdr824vx","What is conjugated (direct) hyperbilirubinemia caused by?","Biliary tract obstruction (gallstones, cholangiocarcinoma, pancreatic cancer, biliary atresia), Dubin-Johnson, Rotor.","Obstrução biliar."],["1irduj7ht","What is mixed hyperbilirubinemia caused by?","Hepatitis, cirrhosis (both direct and indirect).","Hepatite e cirrose."],["o0chbwexl","What is Gilbert syndrome?","Mildly decreased UDP-glucuronosyltransferase activity: benign unconjugated hyperbilirubinemia with fasting, stress, illness.","Icterícia leve benigna no jejum."],["1e2t3se1n","What is Crigler-Najjar type I?","Absent UDP-glucuronosyltransferase: severe unconjugated hyperbilirubinemia and kernicterus in early life; treated with plasmapheresis, phototherapy, liver transplant.","Ausência de UGT; kernicterus."],["1my3l401y","How does Crigler-Najjar type II differ?","Less severe; responds to phenobarbital (increases UGT synthesis).","Mais leve; responde ao fenobarbital."],["p3ndsn1rj","What is Dubin-Johnson syndrome?","Defective liver excretion of conjugated bilirubin (MRP2); black liver; benign.","Fígado preto; benigno."],["3d58qz1xx","What is Rotor syndrome?","Similar to Dubin-Johnson but milder and no black liver (impaired hepatic uptake/storage).","Como Dubin-Johnson, sem fígado preto."],["4phcub606","What is Wilson disease's mechanism and key findings?","ATP7B mutation impairs copper excretion: low ceruloplasmin, cirrhosis, Kayser-Fleischer rings, basal ganglia degeneration, hemolytic anemia.","Excesso de cobre: anéis de Kayser-Fleischer."],["1qv4p8xx7","What is hereditary hemochromatosis's key findings?","Iron overload (HFE C282Y): cirrhosis, diabetes, skin pigmentation, cardiomyopathy, hypogonadism, arthropathy; high ferritin and transferrin saturation.","Excesso de ferro: diabetes bronzeado."],["puikl343e","What is secondary hemochromatosis?","Iron overload from chronic transfusions (e.g., beta-thalassemia major); treated with chelation.","Sobrecarga por transfusões; quelação."],["yle9dx1mg","What is primary biliary cholangitis?","Autoimmune lymphocytic destruction of intralobular bile ducts in middle-aged women; antimitochondrial antibodies; pruritus, fatigue, cholestasis.","Mulheres; antimitocôndria; destruição dos ductos pequenos."],["k924fswh4","Treatment of primary biliary cholangitis?","Ursodiol (ursodeoxycholic acid); obeticholic acid as second line.","Ácido ursodesoxicólico."],["1l4kmra1e","What is primary sclerosing cholangitis?","Concentric onion-skin fibrosis of intra- and extrahepatic bile ducts; beaded appearance on cholangiography; associated with UC; p-ANCA.","Ductos em contas; associada à RCU."],["zg51od6fe","What is the cancer risk of primary sclerosing cholangitis?","Cholangiocarcinoma (and gallbladder cancer, colorectal cancer with UC).","Colangiocarcinoma."],["1rh89tccg","What is secondary biliary cirrhosis?","Cirrhosis from extrahepatic biliary obstruction (gallstones, strictures, cancer).","Cirrose por obstrução biliar."],["jlsudbw5c","What is cholelithiasis?","Gallstones in the gallbladder.","Cálculos na vesícula."],["1rq9lac1v","What is biliary colic?","Neurohormonal activation (CCK after fatty meal) triggers gallbladder contraction against a stone in the cystic duct; postprandial RUQ pain that resolves.","Dor pós-prandial transitória por cálculo."],["1henacb1g","What is acute cholecystitis?","Gallbladder inflammation, usually from cystic duct obstruction by a stone: RUQ pain, fever, leukocytosis, positive Murphy sign.","Inflamação da vesícula; sinal de Murphy."],["oeyh1noud","What is the Murphy sign?","Inspiratory arrest on deep palpation of the RUQ.","Parada da inspiração ao palpar o hipocôndrio direito."],["1kzidi916","Diagnosis of acute cholecystitis?","Ultrasound (thickened wall, pericholecystic fluid, stones); HIDA scan if equivocal (nonvisualized gallbladder).","Ultrassom; cintilografia HIDA se dúvida."],["1ct4o4h15","What is acalculous cholecystitis?","Gallbladder inflammation without stones in critically ill patients (stasis, hypoperfusion).","Colecistite sem cálculo em pacientes graves."],["p98ggly10","What is porcelain gallbladder?","Calcified gallbladder from chronic cholecystitis; increased risk of gallbladder cancer (historically; cholecystectomy considered).","Vesícula calcificada; risco de câncer."],["990xdcoan","What is choledocholithiasis?","Gallstones in the common bile duct: elevated ALP, GGT, direct bilirubin.","Cálculo no colédoco; colestase."],["x28ltf1uq","What is ascending cholangitis?","Infection of the biliary tree from obstruction: Charcot triad of jaundice, fever, RUQ pain.","Infecção biliar: tríade de Charcot."],["768r8r4w7","What is Reynolds pentad?","Charcot triad plus altered mental status and shock (severe cholangitis).","Charcot + confusão + choque."],["1jx0u4u6x","Treatment of ascending cholangitis?","Antibiotics and urgent biliary drainage (ERCP).","Antibiótico e drenagem por CPRE."],["1m6kty61a","What is gallbladder cancer associated with?","Gallstones, porcelain gallbladder; often presents late with cholecystitis-like symptoms.","Cálculos; diagnóstico tardio."],["34rxih1pg","What is cholangiocarcinoma associated with?","Primary sclerosing cholangitis, liver flukes (Clonorchis sinensis), choledochal cysts.","Colangite esclerosante e trematódeos."],["1cpsqpjg9","What is a Klatskin tumor?","Cholangiocarcinoma at the hepatic duct bifurcation.","Colangiocarcinoma na bifurcação dos hepáticos."],["x5jzgvu5v","What is Courvoisier sign?","Painless jaundice with a palpable, nontender gallbladder suggesting malignant obstruction (pancreatic head cancer).","Vesícula palpável indolor com icterícia: câncer de pâncreas."],["13c4tthy8","What is acute pancreatitis?","Autodigestion of the pancreas by pancreatic enzymes.","Autodigestão do pâncreas."],["1vtey1i1y","Most common causes of acute pancreatitis?","Gallstones and alcohol; also hypertriglyceridemia, hypercalcemia, ERCP, drugs, trauma, scorpion sting, mumps.","Cálculos e álcool."],["tput7p17k","Mnemonic for causes of acute pancreatitis?","I GET SMASHED: Idiopathic, Gallstones, Ethanol, Trauma, Steroids, Mumps, Autoimmune, Scorpion, Hypercalcemia/hypertriglyceridemia, ERCP, Drugs.","Mnemônico I GET SMASHED."],["xqf7ms1h0","Clinical features of acute pancreatitis?","Epigastric pain radiating to the back, nausea, vomiting; may have Cullen or Grey Turner signs.","Dor epigástrica em faixa para o dorso."],["qtym331o9","Diagnosis of acute pancreatitis?","Two of three: acute epigastric pain, lipase or amylase >3 times normal, characteristic imaging.","Dois de três critérios."],["1lvg70z19","What are Cullen and Grey Turner signs?","Periumbilical (Cullen) and flank (Grey Turner) ecchymosis from retroperitoneal hemorrhage in severe pancreatitis.","Equimose periumbilical e em flancos."],["7dnw4514f","Complications of acute pancreatitis?","Pseudocyst, necrosis, abscess, hemorrhage, ARDS, shock, DIC, hypocalcemia (fat saponification), renal failure.","Pseudocisto, necrose, SDRA, hipocalcemia."],["15qpp4ssl","Why does acute pancreatitis cause hypocalcemia?","Calcium binds fatty acids released by fat necrosis (saponification).","Cálcio se liga à gordura necrosada."],["1fipl4qe5","What is a pancreatic pseudocyst?","Collection of fluid surrounded by granulation tissue (no epithelial lining), weeks after pancreatitis; may cause pain, infection, rupture.","Coleção sem epitélio após pancreatite."],["142mlau1u","Initial treatment of acute pancreatitis?","Aggressive IV fluids, pain control, early enteral feeding; treat the cause (ERCP for obstructing stones with cholangitis).","Hidratação, analgesia e alimentação precoce."],["ysjxj5ckp","What is chronic pancreatitis?","Chronic inflammation, atrophy, and calcification of the pancreas, most commonly from alcohol (adults) and genetic causes (CF in children).","Inflamação crônica com calcificação."],["o3p8pc18h","Clinical features of chronic pancreatitis?","Chronic epigastric pain, steatorrhea (exocrine insufficiency), diabetes (endocrine insufficiency), weight loss; calcifications on imaging.","Dor crônica, esteatorreia e diabetes."],["jvl9p21r0","Why may amylase and lipase be normal in chronic pancreatitis?","Loss of acinar tissue.","Perda do tecido acinar."],["dokgkwcb1","What is pancreatic adenocarcinoma's typical presentation?","Painless obstructive jaundice (head), abdominal pain radiating to back, weight loss, migratory thrombophlebitis, new-onset diabetes.","Icterícia indolor, emagrecimento, diabetes recente."],["5r06ce1im","Risk factors for pancreatic adenocarcinoma?","Tobacco (strongest), chronic pancreatitis, diabetes, obesity, age >50, BRCA2, Lynch.","Tabagismo é o principal."],["fj4i281vl","Tumor marker for pancreatic adenocarcinoma?","CA 19-9 (also CEA).","CA 19-9."],["9lgqnmn22","What is Trousseau syndrome?","Migratory superficial thrombophlebitis associated with visceral malignancy, classically pancreatic cancer.","Tromboflebite migratória por câncer."],["4gopvc1pj","What surgery is performed for pancreatic head cancer?","Pancreaticoduodenectomy (Whipple procedure).","Cirurgia de Whipple."],["1fdcquynx","What is the prognosis of pancreatic adenocarcinoma?","Very poor; most present with unresectable disease.","Prognóstico muito ruim."],["wty6ph1ot","What are intraductal papillary mucinous neoplasms (IPMN)?","Mucin-producing cystic pancreatic tumors with malignant potential.","Cistos mucinosos com potencial maligno."],["1gvzanf12","What is autoimmune pancreatitis?","IgG4-related disease causing a diffusely enlarged sausage-shaped pancreas; responds to steroids.","Pancreatite por IgG4; responde a corticoide."],["hlxjqz17w","What is the most common cause of hepatitis worldwide transmitted fecal-orally?","Hepatitis A (and E).","Hepatites A e E por via fecal-oral."],["w9uod9arp","Which hepatitis viruses cause chronic infection?","HBV, HCV, HDV (with HBV); HEV in immunocompromised.","B, C e D."],["1v7xqfc12","Which hepatitis causes severe disease in pregnant women?","Hepatitis E (fulminant hepatitis, high mortality).","Hepatite E na gestante."],["12d9zmwcj","What is the meaning of HBsAg positivity?","Ongoing HBV infection (acute or chronic); >6 months indicates chronic.","Infecção ativa pelo HBV."],["u36ukyg14","What does anti-HBs indicate?","Immunity (vaccination or recovered infection).","Imunidade."],["1q2wud9a7","What does HBeAg indicate?","Active viral replication and high transmissibility.","Alta replicação e transmissão."],["1ky3wchjb","What does IgM anti-HBc indicate?","Acute or recent infection; positive during the window period.","Infecção aguda; positivo na janela."],["u3egxj1xw","What is the window period in HBV serology?","HBsAg negative and anti-HBs not yet detectable; IgM anti-HBc is the only marker.","Só anti-HBc IgM positivo."],["halrgcloj","Serology pattern of HBV vaccination?","Anti-HBs positive only.","Apenas anti-HBs."],["2irika1j1","Serology pattern of resolved HBV infection?","Anti-HBs positive and anti-HBc IgG positive.","Anti-HBs e anti-HBc IgG."],["9n61k11yg","What is the histology of viral hepatitis?","Ballooning degeneration, Councilman bodies (apoptotic hepatocytes), mononuclear infiltrate; chronic HBV: ground-glass hepatocytes; HCV: lymphoid aggregates and steatosis.","Corpúsculos de Councilman; vidro fosco no HBV."],["1skwrrb13","Extrahepatic manifestations of hepatitis B?","Polyarteritis nodosa, membranous nephropathy, aplastic anemia.","Poliarterite nodosa e glomerulopatia membranosa."],["1skwrty13","Extrahepatic manifestations of hepatitis C?","Mixed cryoglobulinemia, membranoproliferative GN, porphyria cutanea tarda, lichen planus, B-cell lymphoma, insulin resistance.","Crioglobulinemia, porfiria cutânea, linfoma."],["1loi7318p","What is autoimmune hepatitis?","Chronic hepatitis in young women with anti-smooth muscle or anti-LKM antibodies, high IgG; responds to steroids.","Mulher jovem, anti-músculo liso, responde a corticoide."],["14czr63wz","What is acetaminophen hepatotoxicity's mechanism?","Excess NAPQI depletes glutathione, causing zone III (centrilobular) necrosis.","NAPQI esgota glutationa; necrose centrolobular."],["9l0qou12b","Antidote for acetaminophen overdose?","N-acetylcysteine (regenerates glutathione).","N-acetilcisteína."],["luxnwvfpu","What is ischemic hepatitis (shock liver)?","Massive AST/ALT elevation (thousands) after hypotension, rapid improvement; zone III necrosis.","Transaminases muito altas após hipotensão."],["ntkorj1tc","What causes very high transaminases (>1000)?","Viral hepatitis, ischemic hepatitis, acetaminophen toxicity, autoimmune hepatitis.","Vírus, isquemia, paracetamol."],["rhej5y1xu","What is fulminant hepatic failure?","Acute liver failure with encephalopathy and coagulopathy (INR >1.5) within 8 weeks in a patient without prior liver disease.","Insuficiência hepática aguda com encefalopatia."],["wg6t8q1gl","What is the Child-Pugh score used for?","Assessing severity of cirrhosis (bilirubin, albumin, INR, ascites, encephalopathy).","Gravidade da cirrose."],["1b02tl31o","What is the MELD score used for?","Predicting mortality in end-stage liver disease and prioritizing transplant (bilirubin, INR, creatinine, sodium).","Prioridade para transplante."],["rvutss1en","What is the cause of coagulopathy in liver disease?","Decreased synthesis of clotting factors (except VIII) and vitamin K malabsorption in cholestasis.","Menor síntese de fatores."],["nz4krk8lb","What is the cause of thrombocytopenia in cirrhosis?","Splenic sequestration (hypersplenism) and decreased thrombopoietin.","Sequestro esplênico e pouca trombopoetina."],["9n6319ihd","What is the primary prevention of variceal bleeding?","Nonselective beta-blockers (propranolol, nadolol, carvedilol) or endoscopic band ligation.","Betabloqueador não seletivo ou ligadura."],["1ye6xlejj","Acute treatment of variceal hemorrhage?","Resuscitation, octreotide, antibiotics (ceftriaxone), endoscopic band ligation; TIPS if refractory.","Octreotida, antibiótico e ligadura."],["17mch041e","Why are prophylactic antibiotics given in variceal bleeding?","Reduce risk of SBP and other infections, improving survival.","Reduzem infecções e mortalidade."],["1ssma5zpz","What is the treatment of cirrhotic ascites?","Sodium restriction, spironolactone plus furosemide, large-volume paracentesis with albumin.","Restrição de sódio, espironolactona e furosemida."],["15tr4fq1i","What is a choledochal cyst?","Congenital dilation of the bile duct; risk of cholangiocarcinoma; more common in Asian females.","Dilatação congênita do colédoco."],["1qsgfo1t2","What is biliary atresia's key finding?","Neonatal conjugated hyperbilirubinemia, acholic stools, dark urine after 2 weeks of life.","Icterícia direta e fezes claras no recém-nascido."],["mdoqk91ou","What is the most common indication for liver transplant in children?","Biliary atresia.","Atresia biliar."],["1pbjybqmb","What is hepatoblastoma?","Most common primary liver malignancy in children; elevated AFP; associated with Beckwith-Wiedemann and FAP.","Tumor hepático infantil com AFP alta."],["gz2b441ip","What is congestive hepatopathy?","Liver congestion from right heart failure (nutmeg liver); can progress to cardiac cirrhosis.","Fígado em noz-moscada por insuficiência cardíaca."],["1xi6wld1e","What is a pyogenic liver abscess's common cause?","Biliary infection or hematogenous spread; often E. coli, Klebsiella, anaerobes.","Infecção biliar; E. coli e Klebsiella."],["1jngdyu4p","What is an amebic liver abscess?","Entamoeba histolytica abscess (anchovy paste fluid), often in travelers; treated with metronidazole.","Abscesso amebiano; metronidazol."],["ya3b4raih","What is a hydatid cyst?","Echinococcus granulosus cyst in the liver (eggshell calcification); rupture causes anaphylaxis.","Cisto hidático; ruptura causa anafilaxia."],["1piplgupt","What is peliosis hepatis?","Blood-filled cystic spaces in the liver; associated with anabolic steroids and Bartonella in HIV.","Cavidades com sangue no fígado."],["pm569c1np","What is portal vein thrombosis associated with?","Cirrhosis, hypercoagulable states, malignancy, pancreatitis; causes portal hypertension without cirrhosis.","Cirrose, trombofilia, câncer."],["1euuvcm17","What is nodular regenerative hyperplasia?","Diffuse micronodules without fibrosis causing noncirrhotic portal hypertension; associated with drugs (azathioprine) and autoimmune disease.","Micronódulos sem fibrose; hipertensão portal."],["cgfqv5166","What is the most common cause of pancreatitis in a patient with high triglycerides?","Triglycerides >1000 mg/dL.","Triglicerídeos acima de 1000."],["814ij2urx","Which drugs cause acute pancreatitis?","Azathioprine, valproate, didanosine, thiazides, furosemide, GLP-1 agonists, sulfonamides, corticosteroids, estrogens.","Azatioprina, valproato, diuréticos, entre outros."],["rg1cdjd5p","What is the classic CT finding of chronic pancreatitis?","Pancreatic calcifications and dilated, beaded pancreatic duct (chain of lakes).","Calcificações e ducto em cadeia de lagos."],["hpyyxy1tl","What is the Whipple triad (not the procedure)?","Symptoms of hypoglycemia, low plasma glucose, relief with glucose; suggests insulinoma.","Sintomas, glicemia baixa e melhora com glicose."],["5otasq38e","What is the role of ERCP?","Diagnostic and therapeutic access to the biliary and pancreatic ducts (stone removal, stenting); risk of pancreatitis.","Acesso endoscópico às vias biliares."],["wpyf5y1v5","What is MRCP?","Noninvasive MRI imaging of biliary and pancreatic ducts.","Ressonância das vias biliares."],["gr9wuyzva","What is the classic patient with gallstone pancreatitis?","Middle-aged woman with obesity, ALT >150 suggests gallstone etiology.","Mulher obesa; ALT alta sugere causa biliar."],["hl0rltsw5","When should cholecystectomy be done after gallstone pancreatitis?","During the same admission once the patient recovers (mild cases).","Na mesma internação."],["1hs7hmq1c","What is the classic finding of emphysematous cholecystitis?","Gas in the gallbladder wall, often in diabetic men; Clostridium infection.","Gás na parede da vesícula; diabéticos."],["xz39l51w6","What is Mirizzi syndrome?","Gallstone impacted in the cystic duct or neck compresses the common hepatic duct, causing obstructive jaundice.","Cálculo no ducto cístico comprime o hepático comum."],["1i3azg01x","What is biliary sludge associated with?","Pregnancy, rapid weight loss, TPN, ceftriaxone, octreotide.","Gravidez, emagrecimento rápido, nutrição parenteral."],["5iv393bs3","What is the most common type of gallstone in the US?","Cholesterol stones (radiolucent).","Cálculo de colesterol."],["9z3osf634","What causes black pigment gallstones?","Chronic hemolysis (sickle cell disease, hereditary spherocytosis), cirrhosis, ileal disease; radiopaque.","Hemólise crônica."],["14zatq6is","What causes brown pigment gallstones?","Biliary tract infection (E. coli, Ascaris, Clonorchis); radiolucent; often in bile ducts.","Infecção biliar."],["hz902o12d","What is the definitive treatment for symptomatic cholelithiasis?","Laparoscopic cholecystectomy.","Colecistectomia laparoscópica."],["1j5loctaz","What medication dissolves cholesterol gallstones?","Ursodiol (in selected patients who cannot undergo surgery).","Ácido ursodesoxicólico."],["1shjhw31a","What is the classic lab pattern of extrahepatic obstruction?","High ALP, GGT, direct bilirubin; dark urine, pale stools, pruritus.","FA, GGT e bilirrubina direta altas; prurido."],["1bz6ejgcl","Why does cholestasis cause pruritus?","Bile acid accumulation in the skin.","Acúmulo de sais biliares na pele."],["dzb1l41ke","What are xanthomas in cholestatic liver disease due to?","Hypercholesterolemia from impaired biliary cholesterol excretion.","Colesterol alto por colestase."],["1qyt77b1l","What is the key HCV diagnostic test sequence?","HCV antibody screening, confirmed by HCV RNA PCR.","Anticorpo e depois RNA do HCV."],["kyz1l5j2v","Treatment of chronic hepatitis C?","Direct-acting antivirals (e.g., sofosbuvir-based regimens) achieve cure in most.","Antivirais de ação direta; cura."],["1d457ja3x","Who should be screened for hepatitis C in the US?","All adults at least once, all pregnant women, and people with risk factors.","Todos os adultos ao menos uma vez."],["r1b2ddgcd","What is the role of HCC surveillance?","Ultrasound with or without AFP every 6 months in cirrhosis and high-risk chronic HBV.","Ultrassom a cada 6 meses na cirrose."],["h0utqo2of","What is the transmission route of hepatitis B and C?","Parenteral, sexual, perinatal (HBV much more transmissible sexually and perinatally than HCV).","Sangue, sexo e vertical."],["1sk3d89ha","What is the risk of chronic HBV after infection at birth vs adulthood?","About 90% of infected newborns become chronic vs <5% of adults.","Recém-nascido cronifica em 90%; adulto em <5%."],["f8xbal4jz","How is perinatal HBV transmission prevented?","HBV vaccine and hepatitis B immune globulin to the newborn within 12 hours; maternal tenofovir if high viral load.","Vacina e imunoglobulina ao nascer."],["vd20ap7mm","What is hepatitis D?","Defective virus requiring HBsAg coat; coinfection or superinfection with HBV worsens disease.","Vírus defectivo que depende do HBV."],["19kvte916","What is the classic exposure for hepatitis A?","Contaminated food or water, travel, shellfish; acute self-limited; IgM anti-HAV.","Alimento e água contaminados; autolimitada."],["19kvtat16","What is the classic exposure for hepatitis E?","Contaminated water, undercooked pork or game; severe in pregnancy.","Água contaminada e carne de porco mal cozida."],["x3qrlo19k","What is the earliest sign of liver disease on exam in many patients?","Scleral icterus when bilirubin exceeds about 2.5-3 mg/dL.","Icterícia nas escleras."],["y7yoli96d","What is the cause of hypoalbuminemia in cirrhosis?","Decreased hepatic synthesis.","Menor síntese hepática."],["1xxw7gf1l","What is the cause of hyponatremia in cirrhosis?","Increased ADH from reduced effective circulating volume (dilutional).","Excesso de ADH; diluição."],["6elybri5k","What is the hepatic lesion of a patient taking oral contraceptives who presents with sudden abdominal pain and hypotension?","Ruptured hepatic adenoma.","Adenoma hepático rompido."],["sep3t51f0","What is the most common cause of acute liver failure in the US?","Acetaminophen overdose.","Intoxicação por paracetamol."],["227uct3pp","What is the Rumack-Matthew nomogram used for?","Determining need for N-acetylcysteine after a single acute acetaminophen ingestion based on timed serum level.","Decide uso de N-acetilcisteína."],["yidx1r1nc","What causes jaundice in sickle cell disease?","Hemolysis (unconjugated) and pigment gallstones causing obstruction.","Hemólise e cálculos pigmentados."],["1pvr8lctc","What is the main pancreatic finding in cystic fibrosis?","Exocrine insufficiency from thick secretions obstructing ducts (fibrosis and fatty replacement).","Insuficiência exócrina por secreções espessas."]]},{"name":"Pharmacology","cards":[["mocmhn2k7","Mechanism of H2 receptor antagonists?","Reversible block of histamine H2 receptors on parietal cells, decreasing H+ secretion (cimetidine, famotidine, nizatidine).","Bloqueiam H2 e reduzem o ácido."],["1uo0ru7nd","Clinical uses of H2 blockers?","Peptic ulcer, gastritis, mild esophageal reflux.","Úlcera, gastrite, refluxo leve."],["doir4s142","Adverse effects of cimetidine?","Potent CYP450 inhibitor; antiandrogenic effects (gynecomastia, impotence, decreased libido); crosses BBB (confusion) and placenta.","Inibe CYP450; ginecomastia."],["1kdrvp3qq","Which H2 blocker decreases renal creatinine excretion?","Cimetidine (also ranitidine historically).","Cimetidina."],["16kq1pbfg","Mechanism of proton pump inhibitors?","Irreversibly inhibit H+/K+-ATPase in stomach parietal cells (omeprazole, lansoprazole, esomeprazole, pantoprazole).","Inibem a bomba de prótons de forma irreversível."],["1wudjo62r","Clinical uses of PPIs?","Peptic ulcer, gastritis, GERD, Zollinger-Ellison syndrome, H. pylori eradication, stress ulcer prophylaxis.","Úlcera, DRGE, Zollinger-Ellison, H. pylori."],["hoea7q1bl","Adverse effects of long-term PPIs?","C. difficile infection, pneumonia, acute interstitial nephritis, decreased B12, Ca2+, Mg2+, iron absorption, fractures, fundic gland polyps.","C. difficile, hipomagnesemia, fraturas, baixa B12."],["1hxxg2eap","When should PPIs be taken relative to meals?","About 30 minutes before a meal (pumps are activated by food).","30 minutos antes da refeição."],["112ba331o","Mechanism of antacids?","Neutralize gastric acid; can affect absorption, bioavailability, and urinary excretion of other drugs.","Neutralizam o ácido."],["ovxchwsrb","Adverse effect of aluminum hydroxide?","Constipation, hypophosphatemia, osteodystrophy, proximal muscle weakness, seizures.","Constipação e hipofosfatemia."],["1ve8czyzv","Adverse effect of calcium carbonate antacids?","Hypercalcemia (milk-alkali syndrome), rebound acid secretion.","Hipercalcemia e rebote ácido."],["12j94a41f","Adverse effect of magnesium hydroxide?","Diarrhea, hyporeflexia, hypotension, cardiac arrest (hypermagnesemia).","Diarreia; hipermagnesemia."],["8vdv3ei4r","Mnemonic for antacid side effects?","Aluminimum amount of feces (constipation); Mg causes Must go to the bathroom (diarrhea).","Alumínio prende, magnésio solta."],["o6d3v71nv","Mechanism of bismuth and sucralfate?","Bind to ulcer base, providing physical protection; sucralfate requires acidic environment; bismuth helps eradicate H. pylori.","Protegem a base da úlcera."],["15nn48ae2","Adverse effect of bismuth?","Black stools and black tongue.","Fezes e língua pretas."],["mruty11j4","Mechanism of misoprostol?","PGE1 analog: increases mucus and bicarbonate secretion, decreases acid production.","Análogo de prostaglandina que protege a mucosa."],["tig3wy1j9","Uses of misoprostol?","Prevention of NSAID-induced ulcers, maintenance of PDA, labor induction (cervical ripening), medical abortion with mifepristone.","Prevenção de úlcera por AINE; indução do parto."],["12igwsu1s","Adverse effects and contraindication of misoprostol?","Diarrhea; contraindicated in women of childbearing potential not using contraception (abortifacient).","Diarreia; abortivo."],["ef7uoljj7","Mechanism and use of octreotide in GI?","Long-acting somatostatin analog: acute variceal bleeding, acromegaly, VIPoma, carcinoid syndrome.","Análogo da somatostatina; varizes e carcinoide."],["rssl40y6o","Mechanism and use of loperamide?","Mu-opioid agonist with poor CNS penetration; slows gut motility; antidiarrheal.","Opioide periférico antidiarreico."],["92p1kc1kw","Mechanism and use of diphenoxylate?","Opioid antidiarrheal combined with atropine to discourage abuse.","Antidiarreico opioide com atropina."],["180rti3e7","Mechanism and use of ondansetron?","5-HT3 antagonist; decreases vagal stimulation; powerful central-acting antiemetic for chemotherapy and postoperative nausea.","Antagonista 5-HT3; antiemético."],["e9mc663ei","Adverse effects of ondansetron?","Headache, constipation, QT prolongation, serotonin syndrome.","Cefaleia, constipação, QT longo."],["igfovp4ts","Mechanism and use of metoclopramide?","D2 receptor antagonist; increases resting LES tone and gastric emptying; diabetic gastroparesis, antiemetic.","Antagonista D2 procinético."],["g26ys01ay","Adverse effects of metoclopramide?","Extrapyramidal symptoms, tardive dyskinesia, restlessness, drowsiness, hyperprolactinemia, depression; contraindicated in small bowel obstruction or Parkinson disease.","Sintomas extrapiramidais e discinesia tardia."],["1yzg6pcp5","Mechanism and use of aprepitant?","NK1 (substance P) receptor antagonist; chemotherapy-induced nausea and vomiting.","Antagonista NK1; náusea da quimioterapia."],["mozzcy1es","Mechanism and use of prochlorperazine and promethazine?","D2 antagonists (promethazine also H1); antiemetics.","Antieméticos antidopaminérgicos."],["70rqfyqxl","Mechanism of erythromycin as a prokinetic?","Motilin receptor agonist, stimulating gastric motility (gastroparesis).","Agonista da motilina."],["1imrfojqn","Osmotic laxatives and mechanism?","Lactulose, magnesium hydroxide, polyethylene glycol: provide osmotic load to draw water into the lumen.","Puxam água para o intestino."],["gb5dtm1ev","How does lactulose treat hepatic encephalopathy?","Gut flora degrade it to metabolites that acidify the lumen, converting NH3 to NH4+ (trapped and excreted).","Acidifica o cólon e prende a amônia."],["1hk5y0y1a","Stimulant laxatives and mechanism?","Senna, bisacodyl: enteric nerve stimulation and colonic contraction.","Estimulam nervos e contração do cólon."],["jf9zw01fz","Adverse effect of chronic senna use?","Melanosis coli (brown pigmentation of colon).","Melanose do cólon."],["1n5e5whuj","Emollient laxative and mechanism?","Docusate: promotes incorporation of water into stool.","Amolece as fezes."],["1uhv0j01g","Adverse effects of laxatives?","Diarrhea, dehydration; may be abused by patients with eating disorders.","Diarreia e desidratação."],["1ezjh6k1p","Mechanism and use of lubiprostone?","Chloride channel (ClC-2) activator increasing intestinal fluid; chronic constipation and IBS-C.","Ativa canal de cloro; constipação."],["1lisw9i1n","Mechanism and use of linaclotide?","Guanylate cyclase-C agonist increasing cGMP and intestinal fluid secretion; IBS-C and chronic constipation.","Agonista da guanilato ciclase; constipação."],["1nj2tpf1h","Mechanism and use of methylnaltrexone and naloxegol?","Peripheral mu-opioid antagonists for opioid-induced constipation.","Antagonistas opioides periféricos."],["1yox6h6hd","Mechanism and use of sulfasalazine?","Combination of sulfapyridine (antibacterial) and 5-ASA (anti-inflammatory) activated by colonic bacteria; UC, Crohn colitis, rheumatoid arthritis.","5-ASA + sulfapiridina; RCU e artrite."],["q2jq1b6px","Adverse effects of sulfasalazine?","Malaise, nausea, sulfonamide toxicity, reversible oligospermia, folate deficiency.","Oligospermia reversível e falta de folato."],["s4cp8w15f","Mechanism of mesalamine?","5-ASA that acts locally in the gut to reduce inflammation; first-line for mild to moderate UC.","5-ASA de ação local; RCU."],["1914eufz5","Which biologics are used in IBD?","Anti-TNF (infliximab, adalimumab, certolizumab), anti-integrin (vedolizumab), anti-IL-12/23 (ustekinumab), anti-IL-23 (risankizumab), JAK inhibitors (tofacitinib, upadacitinib).","Anti-TNF, vedolizumabe, ustequinumabe, inibidores de JAK."],["17jfwr5hy","What must be done before starting anti-TNF therapy?","Screen for latent TB and hepatitis B (risk of reactivation).","Rastrear tuberculose latente e hepatite B."],["1nkwsusnj","Mechanism of vedolizumab?","Monoclonal antibody against alpha4-beta7 integrin, blocking gut-specific leukocyte migration.","Bloqueia a integrina intestinal α4β7."],["1q5wznw3n","Mechanism of budesonide in IBD?","Glucocorticoid with high first-pass metabolism, limiting systemic effects; Crohn ileitis and microscopic colitis.","Corticoide com pouco efeito sistêmico."],["sab6dp1as","Mechanism of azathioprine and 6-MP in IBD?","Purine analogs inhibiting lymphocyte proliferation; steroid-sparing maintenance.","Imunossupressores poupadores de corticoide."],["16dd3mup4","What test is done before azathioprine therapy?","TPMT activity (and NUDT15) to predict myelosuppression risk.","Atividade da TPMT."],["vce03metj","Mechanism of orlistat?","Inhibits gastric and pancreatic lipase, decreasing fat breakdown and absorption.","Inibe a lipase; menos gordura absorvida."],["9mmcy7i4h","Adverse effects of orlistat?","Abdominal pain, flatulence, bowel urgency, oily stools, decreased absorption of fat-soluble vitamins.","Fezes oleosas e falta de vitaminas lipossolúveis."],["8iamfpepp","Mechanism and use of ursodiol?","Bile acid that decreases cholesterol secretion and reabsorption; primary biliary cholangitis, gallstone dissolution, prevention in rapid weight loss.","Ácido biliar; colangite biliar primária e cálculos."],["1m92eeezj","Mechanism and use of cholestyramine in GI?","Bile acid sequestrant; pruritus from cholestasis and bile acid diarrhea.","Sequestrante de ácidos biliares; prurido."],["x8ltvk1ji","Treatment of H. pylori (common regimens)?","Clarithromycin triple therapy (PPI + clarithromycin + amoxicillin or metronidazole) or bismuth quadruple therapy (PPI + bismuth + metronidazole + tetracycline).","Tripla com claritromicina ou quádrupla com bismuto."],["1f5uq2912","How is H. pylori eradication confirmed?","Urea breath test or stool antigen at least 4 weeks after therapy (off PPI for 2 weeks).","Teste respiratório ou antígeno fecal após 4 semanas."],["1agc2nu1f","Treatment of hepatitis B?","Tenofovir or entecavir (nucleoside/nucleotide analogs); interferon in selected cases.","Tenofovir ou entecavir."],["1agc2l71f","Treatment of hepatitis C?","Direct-acting antivirals: NS5B polymerase inhibitor (sofosbuvir), NS5A inhibitors (ledipasvir, velpatasvir), NS3/4A protease inhibitors (glecaprevir, grazoprevir).","Antivirais de ação direta."],["3xoshggom","Mechanism of sofosbuvir?","Inhibits HCV NS5B RNA-dependent RNA polymerase (chain terminator).","Inibe a polimerase NS5B."],["1g3b0vh11","Mechanism of ledipasvir and velpatasvir?","Inhibit NS5A, a protein involved in viral replication and assembly.","Inibem NS5A."],["124cojy1i","Mechanism of glecaprevir and grazoprevir?","Inhibit NS3/4A protease, preventing viral polyprotein cleavage.","Inibem a protease NS3/4A."],["7xzew7169","Mechanism and use of rifaximin?","Nonabsorbable antibiotic reducing ammonia-producing gut bacteria; hepatic encephalopathy, traveler's diarrhea, IBS-D, SIBO.","Antibiótico não absorvível; encefalopatia hepática."],["tsuv8vxqe","Mechanism of terlipressin in hepatorenal syndrome?","Vasopressin analog causing splanchnic vasoconstriction, improving renal perfusion (with albumin).","Vasoconstrição esplâncnica; melhora o rim."],["19tltojt5","Why are nonselective beta-blockers used in portal hypertension?","Beta1 blockade lowers cardiac output; beta2 blockade allows splanchnic vasoconstriction, lowering portal pressure.","Reduzem a pressão portal."],["etr9u11xi","Mechanism and use of pancrelipase?","Pancreatic enzyme replacement (lipase, amylase, protease) for exocrine pancreatic insufficiency.","Reposição de enzimas pancreáticas."],["16rbjom14","Treatment of C. difficile infection?","Oral fidaxomicin or oral vancomycin; fecal microbiota transplant for recurrent infection; bezlotoxumab to reduce recurrence.","Fidaxomicina ou vancomicina oral."],["96obg3169","Why is oral vancomycin used for C. difficile but IV vancomycin is not?","Oral vancomycin is not absorbed and reaches high colonic concentrations; IV does not reach the colon lumen.","Só a oral chega ao cólon."],["1sogsh6ph","Mechanism and use of dicyclomine and hyoscyamine?","Antimuscarinic antispasmodics for IBS cramping.","Antiespasmódicos anticolinérgicos."],["10tifmdfn","Which antidepressants are used in IBS?","TCAs (amitriptyline) for pain and diarrhea-predominant IBS; SSRIs in some.","Tricíclicos em baixa dose."],["esc2pf10a","Mechanism and use of alosetron?","5-HT3 antagonist for severe diarrhea-predominant IBS in women; risk of ischemic colitis.","Para SII com diarreia; risco de colite isquêmica."],["o9dqo01cj","Mechanism and use of eluxadoline?","Mixed opioid receptor agonist/antagonist for IBS-D; risk of pancreatitis.","Opioide misto para SII com diarreia."],["tbdfrseh8","Mechanism and use of tegaserod?","5-HT4 agonist increasing motility for IBS-C (restricted use).","Agonista 5-HT4; SII com constipação."],["ywvqws19n","Mechanism and use of prucalopride?","Selective 5-HT4 agonist for chronic idiopathic constipation.","Agonista 5-HT4 para constipação."],["1p4gq6o1y","Mechanism and use of dronabinol?","Cannabinoid receptor agonist; chemotherapy-induced nausea and AIDS-related anorexia.","Canabinoide para náusea e anorexia."],["1p630nl4l","Mechanism and use of scopolamine as antiemetic?","Antimuscarinic; motion sickness (transdermal patch).","Anticolinérgico para cinetose."],["1rh72pix4","Mechanism and use of meclizine?","H1 antagonist (antihistamine) for vertigo and motion sickness.","Anti-histamínico para vertigem."],["vsbolsg5l","Which drug class is best for nausea from vestibular causes?","Antihistamines and anticholinergics (meclizine, scopolamine).","Anti-histamínicos e anticolinérgicos."],["17leuwz1u","Which drug is used for stress ulcer prophylaxis in ICU?","PPIs or H2 blockers.","IBP ou bloqueador H2."],["abaaynzc8","What drugs cause pill esophagitis?","Bisphosphonates, NSAIDs, tetracyclines, potassium chloride, iron, quinidine.","Bisfosfonatos, tetraciclinas, potássio, ferro."],["k129ywxkv","What drug class increases risk of GI bleeding when combined with SSRIs?","NSAIDs (and anticoagulants/antiplatelets).","AINEs."],["1vb5o9q1r","Which NSAID type reduces GI toxicity?","Selective COX-2 inhibitors (celecoxib), with increased cardiovascular risk.","Inibidores seletivos da COX-2."],["e9jyoc1ml","What is the mechanism of NSAID-induced GI damage?","COX-1 inhibition decreases protective prostaglandins in the gastric mucosa.","Menos prostaglandinas protetoras."],["e3g2c111z","What drugs are associated with drug-induced hepatitis?","Isoniazid, acetaminophen (overdose), halothane, valproate, amiodarone, statins, methotrexate, ketoconazole.","Isoniazida, paracetamol, valproato, amiodarona."],["1ogzac31d","Which drugs cause cholestatic liver injury?","Amoxicillin-clavulanate, anabolic steroids, oral contraceptives, chlorpromazine, erythromycin.","Amoxicilina-clavulanato, anabolizantes, anticoncepcionais."],["2egs1u1n5","Which drug causes hepatic fibrosis with long-term use?","Methotrexate (also vitamin A excess).","Metotrexato."],["16aiyd7fo","Which anesthetic causes hepatic necrosis?","Halothane.","Halotano."],["1pr9p35ju","Which antibiotic causes liver toxicity and requires LFT monitoring in TB therapy?","Isoniazid (also rifampin, pyrazinamide).","Isoniazida."],["1pj7sae1b","Which drug causes pancreatitis and is used in IBD?","Azathioprine (also mesalamine rarely).","Azatioprina."],["7zjjoj1u1","Which antiemetic is safe and first-line in pregnancy?","Pyridoxine (vitamin B6) with doxylamine.","Piridoxina com doxilamina."],["1wmqunz1g","What is the mechanism of polyethylene glycol bowel prep?","Nonabsorbable osmotic agent causing large-volume diarrhea for colonoscopy preparation.","Laxante osmótico para preparo de colonoscopia."],["1avjj2ugn","What is the risk of sodium phosphate bowel preparation?","Acute phosphate nephropathy.","Nefropatia por fosfato."],["1xb24yp1s","What is the mechanism of simethicone?","Reduces surface tension of gas bubbles (antiflatulent).","Reduz bolhas de gás."],["1yi1z931h","Which drug is used to treat Wilson disease by blocking copper absorption?","Zinc (induces metallothionein).","Zinco."],["12amd0ne8","Which chelator is used for Wilson disease?","Penicillamine or trientine.","Penicilamina ou trientina."],["1gtf73v12","What is the treatment for autoimmune hepatitis?","Glucocorticoids (prednisone) with or without azathioprine.","Corticoide com ou sem azatioprina."],["4b9et2uaf","What drug is used to prevent recurrent hepatic encephalopathy besides lactulose?","Rifaximin.","Rifaximina."]]},{"name":"Physiology","cards":[["jz1gvh5cl","Where is gastrin produced and what does it do?","G cells of the antrum and duodenum; increases gastric H+ secretion, growth of gastric mucosa, and gastric motility.","Gastrina estimula ácido e motilidade."],["8stvg5f61","What stimulates and inhibits gastrin release?","Stimulated by stomach distension, alkalinization, amino acids, peptides, vagal stimulation (GRP); inhibited by pH <1.5.","Distensão e aminoácidos estimulam; ácido inibe."],["16qmna516","What causes high gastrin levels?","Zollinger-Ellison syndrome (gastrinoma), chronic PPI use, chronic atrophic gastritis (e.g., H. pylori, pernicious anemia).","Gastrinoma, IBP, gastrite atrófica."],["1bnsix3gw","Where is somatostatin produced in the GI tract and what does it do?","D cells of pancreatic islets and GI mucosa; decreases gastric acid, pepsinogen, pancreatic and small intestine fluid secretion, gallbladder contraction, insulin and glucagon release.","Somatostatina inibe secreções."],["28qfq4njj","What stimulates and inhibits somatostatin?","Stimulated by acid; inhibited by vagal stimulation.","Ácido estimula; vago inibe."],["4ssyeq1sz","Where is CCK produced and what does it do?","I cells of duodenum and jejunum; increases pancreatic enzyme secretion, gallbladder contraction, sphincter of Oddi relaxation; decreases gastric emptying.","CCK: enzimas e contração da vesícula."],["1062ix7gz","What stimulates CCK release?","Fatty acids and amino acids in the duodenum.","Gordura e aminoácidos no duodeno."],["4xjx54yx4","Where is secretin produced and what does it do?","S cells of the duodenum; increases pancreatic bicarbonate secretion, decreases gastric acid secretion, increases bile secretion.","Secretina: bicarbonato pancreático."],["1umujzl2r","What stimulates secretin release?","Acid and fatty acids in the duodenal lumen.","Ácido no duodeno."],["1oeaodj16","Where is GIP produced and what does it do?","K cells of duodenum and jejunum; endocrine: increases insulin release; exocrine: decreases gastric acid secretion.","GIP: libera insulina."],["oir5g21be","What does motilin do?","Produced by small intestine; produces migrating motor complexes (MMCs) during fasting; erythromycin is a motilin agonist.","Complexo motor migratório."],["11z9zt5bf","What does VIP do in the GI tract?","Increases intestinal water and electrolyte secretion; relaxes intestinal smooth muscle and sphincters.","VIP: secreção e relaxamento."],["1hvz0ze17","What is the role of nitric oxide in the GI tract?","Relaxes smooth muscle including the LES; loss of NO in the LES contributes to achalasia.","Óxido nítrico relaxa o EEI."],["va74qf1gw","What is ghrelin's GI role?","Produced in the stomach; increases appetite (orexigenic).","Grelina dá fome."],["iegnay10h","What does gastric acid secretion depend on?","Parietal cells via H+/K+-ATPase; stimulated by histamine (H2), ACh (M3), gastrin (CCK-B).","Bomba H+/K+ das células parietais."],["jjnwd5t65","How do histamine, ACh, and gastrin increase acid secretion mechanistically?","Histamine via Gs/cAMP; ACh and gastrin via Gq/Ca2+; gastrin also stimulates ECL cells to release histamine.","Histamina por AMPc; ACh e gastrina por cálcio."],["uvfgic1i0","What does intrinsic factor do?","Secreted by parietal cells; binds vitamin B12 for absorption in the terminal ileum.","Liga a B12."],["1x2695o1y","What do chief cells secrete?","Pepsinogen, converted to pepsin by H+; also gastric lipase.","Pepsinogênio."],["jd3ccw1pd","What do mucous cells of the stomach secrete?","Mucus and bicarbonate to protect the gastric mucosa.","Muco e bicarbonato."],["dttjntdv6","What do Brunner glands secrete?","Alkaline mucus to neutralize acid in the duodenum; hypertrophy in peptic ulcer disease.","Muco alcalino."],["eor7h36jb","What does pancreatic secretion contain?","Isotonic fluid with bicarbonate (from ductal cells) and enzymes (from acinar cells).","Bicarbonato e enzimas."],["9zczuwlrw","How does flow rate affect pancreatic juice composition?","Low flow: high Cl-. High flow: high HCO3-.","Fluxo alto: mais bicarbonato."],["ixhqwp1yh","Which pancreatic enzymes digest carbohydrates, proteins, fats?","Alpha-amylase (starch), proteases (trypsin, chymotrypsin, elastase, carboxypeptidases), lipase, phospholipase A2, colipase.","Amilase, proteases e lipase."],["1u2a8ad17","How is trypsinogen activated?","By enterokinase/enteropeptidase on the duodenal brush border; trypsin then activates other proenzymes and more trypsinogen.","Enteroquinase ativa a tripsina."],["1o3221y1i","Why is premature trypsin activation dangerous?","It activates other enzymes within the pancreas, causing autodigestion (pancreatitis).","Autodigestão e pancreatite."],["4hemftqcs","How are carbohydrates absorbed in the small intestine?","Only monosaccharides are absorbed: glucose and galactose via SGLT1 (Na+-dependent), fructose via GLUT5 (facilitated diffusion); all exit via GLUT2.","Só monossacarídeos são absorvidos."],["1hnk12dtq","What is the D-xylose absorption test used for?","Distinguishes GI mucosal damage from other causes of malabsorption: normal urinary excretion in pancreatic insufficiency, decreased in mucosal disease or bacterial overgrowth.","Diferencia lesão da mucosa."],["sxtgu11es","Where is iron absorbed?","Duodenum (as Fe2+).","Duodeno."],["rafcfq1ca","Where is folate absorbed?","Small bowel (jejunum).","Jejuno."],["oomnoie3a","Where is vitamin B12 absorbed?","Terminal ileum, with intrinsic factor (along with bile salts).","Íleo terminal."],["80ou0v1dg","Mnemonic for absorption sites of iron, folate, B12?","Iron Fist, Bro: Iron in duodenum, Folate in jejunum (small bowel), B12 in ileum.","Ferro, folato, B12."],["1t5pbp41h","What are bile salts composed of?","Bile acids conjugated to glycine or taurine, making them water soluble.","Ácidos biliares conjugados."],["xcm7391it","What are the functions of bile?","Digestion and absorption of lipids and fat-soluble vitamins, cholesterol excretion, antimicrobial activity (membrane disruption), bilirubin excretion.","Digestão de gordura e excreção."],["1ako0xz30","What happens to bile salts in the ileum?","95% are reabsorbed and recycled to the liver (enterohepatic circulation).","95% reabsorvidos."],["1t7r94esj","What is the consequence of ileal resection on bile salts?","Bile acid malabsorption: diarrhea, steatorrhea, fat-soluble vitamin deficiency, gallstones, calcium oxalate kidney stones.","Diarreia, esteatorreia, cálculos."],["1too19w1x","Why does fat malabsorption cause calcium oxalate stones?","Unabsorbed fat binds calcium, leaving free oxalate to be absorbed in the colon.","Gordura prende o cálcio; oxalato sobra."],["11y7smn15","What is bilirubin's source?","Heme metabolism (mostly from senescent RBCs) by macrophages in the spleen.","Degradação do heme."],["1isz2g561","How is bilirubin conjugated and excreted?","Unconjugated bilirubin is bound to albumin, taken up by the liver, conjugated with glucuronate by UGT, excreted in bile.","Conjugada no fígado e excretada na bile."],["1va5r6o3q","What gives stool its brown color?","Stercobilin (from bacterial conversion of urobilinogen).","Estercobilina."],["ca7630u4n","What gives urine its yellow color?","Urobilin (from reabsorbed urobilinogen).","Urobilina."],["1j5oz8o3m","What happens to urine urobilinogen in obstructive jaundice?","Decreased (no bilirubin reaches the gut); urine is dark from conjugated bilirubin, stool is pale.","Urobilinogênio diminui."],["7tp7gsqmw","What happens to urine urobilinogen in hemolytic jaundice?","Increased; no bilirubin in urine (unconjugated is not water soluble).","Urobilinogênio aumenta."],["1kpak475b","What are the phases of swallowing?","Oral (voluntary), pharyngeal (involuntary, UES relaxes), esophageal (peristalsis, LES relaxation).","Oral, faríngea e esofágica."],["1vsdetnwn","What controls receptive relaxation of the stomach?","Vagovagal reflex mediated by VIP and NO.","Reflexo vagovagal."],["r1ymikak1","What is the migrating motor complex?","Cyclic fasting motility (every 90-120 min) that sweeps undigested material through the gut; mediated by motilin.","Ondas no jejum pela motilina."],["1t2ju5h11","What is the gastrocolic reflex?","Food in the stomach increases colonic motility (urge to defecate after meals).","Comer estimula o cólon."],["1d4o23s1s","What slows gastric emptying?","Fat and acid in the duodenum (CCK, secretin, GIP), hyperosmolar contents.","Gordura e ácido no duodeno."],["7q9r1qc8g","What is the main site of water absorption in the GI tract?","Small intestine (jejunum); colon absorbs the remainder.","Intestino delgado."],["qw40fc9vz","How is sodium absorbed in the colon?","ENaC channels (aldosterone-regulated).","Canais ENaC."],["1r7j5zv1b","What is the mechanism of secretory diarrhea from cholera?","Cholera toxin permanently activates Gs, increasing cAMP and CFTR-mediated Cl- secretion, causing watery diarrhea.","Toxina ativa Gs e cloro sai."],["1k0876gct","How is secretory diarrhea distinguished from osmotic diarrhea?","Secretory: low stool osmotic gap, persists with fasting. Osmotic: high stool osmotic gap (>125), stops with fasting.","Gap osmótico fecal."],["148nk5l1s","What does a stool osmotic gap measure?","290 - 2(stool Na+ + stool K+); high in osmotic diarrhea.","Gap osmótico das fezes."],["10rmt2jna","What is the role of salivary amylase?","Begins starch digestion in the mouth (inactivated by gastric acid).","Começa a digerir amido."],["s787b15j8","What does saliva contain?","Alpha-amylase, lingual lipase, bicarbonate, mucins, IgA, lysozyme; hypotonic.","Amilase, lipase, IgA, lisozima."],["1q0xg9nad","How does saliva composition change with flow rate?","Higher flow: less time for modification, so more Na+, Cl- and less K+ (closer to plasma).","Fluxo alto parece com plasma."],["119n1svlp","Which autonomic system increases saliva production?","Both sympathetic (thick, protein-rich via T1-T3 superior cervical ganglion) and parasympathetic (watery via CN VII, IX).","Simpático e parassimpático."],["6r4o5d1fk","What is the function of peptide YY?","Released from ileum and colon after meals; inhibits gastric emptying and appetite (ileal brake).","Freio ileal."],["13zzeyevl","What is the role of the enteric nervous system?","Independent neural control of GI motility and secretion (myenteric and submucosal plexuses).","Controle próprio do intestino."],["cwl1wt1oh","How is fat absorbed?","Micelles deliver fatty acids and monoglycerides to enterocytes; re-esterified into triglycerides; packaged into chylomicrons; enter lymphatics (lacteals).","Micelas e quilomícrons."],["3yvpwbclb","Why are medium-chain triglycerides absorbed differently?","Absorbed directly into portal blood without micelles or chylomicrons.","Absorvidos direto no sangue portal."],["iofib62h9","Where are most nutrients absorbed?","Duodenum and jejunum.","Duodeno e jejuno."],["6n0d41317","What are the main sites of calcium absorption?","Duodenum and jejunum (vitamin D dependent transcellular transport in duodenum).","Duodeno e jejuno."],["1tbbbawk8","What is the role of the ileocecal valve?","Prevents reflux of colonic contents and regulates flow of ileal contents into the colon.","Impede refluxo do cólon."],["1vhgaoe1q","What is the role of colonic bacteria?","Ferment carbohydrates to short-chain fatty acids (butyrate for colonocytes), produce vitamin K and biotin, deconjugate bile salts, convert bilirubin.","Fermentação, vitamina K, sais biliares."],["762pln1sq","Which short-chain fatty acid is the main fuel for colonocytes?","Butyrate.","Butirato."],["11v27xy1w","What regulates gastric acid at the cephalic phase?","Vagal stimulation (sight, smell, thought of food) via ACh and GRP.","Fase cefálica pelo vago."],["zx6xaurn5","What regulates gastric acid at the gastric phase?","Stomach distension and amino acids stimulate gastrin and acid.","Fase gástrica: distensão e gastrina."],["yv6z10ht8","What regulates gastric acid at the intestinal phase?","Acid, fat, and hyperosmolar chyme in duodenum inhibit acid (secretin, GIP, somatostatin) and stimulate pancreatic secretion.","Fase intestinal inibe o ácido."],["lbh09y1c9","What is the alkaline tide?","Postprandial increase in blood pH and urine pH as parietal cells secrete H+ and add bicarbonate to the blood.","Sangue alcaliniza após refeição."],["hbkuxr1ug","What are the defecation reflex components?","Rectal distension relaxes internal anal sphincter (involuntary); external sphincter (voluntary, pudendal nerve) is relaxed to defecate.","Esfíncteres interno e externo."],["t3kfr3h4m","What is the role of the liver in glucose homeostasis?","Glycogen storage and breakdown, gluconeogenesis.","Glicogênio e gliconeogênese."],["xjpq81brl","What proteins does the liver synthesize?","Albumin, clotting factors (except VIII from endothelium), complement, transport proteins, acute phase proteins, lipoproteins.","Albumina, fatores, complemento."],["mkfcnf1o2","What is the albumin half-life and why is it a poor marker of acute liver failure?","About 20 days; slow to fall acutely. PT/INR is better for acute synthetic function.","Meia-vida de 20 dias."],["jv5eqtgoo","Which lab is the best marker of acute hepatic synthetic function?","Prothrombin time/INR (factor VII has the shortest half-life).","Tempo de protrombina."],["mhp0tc1wc","Which liver enzyme rises more in alcoholic hepatitis?","AST > ALT (ratio often >2:1).","AST maior que ALT."],["28idds9ce","Which liver enzyme rises more in viral hepatitis?","ALT > AST.","ALT maior que AST."],["p1eb4m1l3","Which liver enzymes suggest cholestasis?","Alkaline phosphatase and GGT elevated.","FA e GGT."],["bavgc514j","Why is GGT useful with elevated alkaline phosphatase?","Elevated GGT confirms hepatic (biliary) source; normal GGT suggests bone source.","GGT confirma origem biliar."],["51sqc239y","What does an elevated ammonia indicate in liver disease?","Impaired urea cycle function; associated with hepatic encephalopathy (although levels correlate imperfectly).","Falha do ciclo da ureia."],["81ldkn1ez","What does elevated serum amylase or lipase indicate?","Acute pancreatitis (lipase more specific); also mumps (amylase), perforated ulcer.","Pancreatite."],["1h6lbvt83","What does ceruloplasmin measure clinically?","Decreased in Wilson disease.","Baixa na doença de Wilson."],["14iy4n51p","What does alpha-fetoprotein indicate in liver disease?","Hepatocellular carcinoma (also hepatoblastoma, yolk sac tumor).","Carcinoma hepatocelular."],["8oqxvhk1w","Which marker suggests primary biliary cholangitis?","Antimitochondrial antibodies.","Antimitocôndria."],["1mugnz9zh","Which marker suggests autoimmune hepatitis?","Anti-smooth muscle antibodies and anti-LKM-1 antibodies (type 2).","Antimúsculo liso."],["113zr61uz","What is the role of the gallbladder?","Stores and concentrates bile; contracts in response to CCK.","Armazena e concentra bile."],["m94v7vfc4","What forms gallstones?","Imbalance between cholesterol, bile salts, and phosphatidylcholine; bile stasis; increased bilirubin (pigment stones).","Excesso de colesterol ou bilirrubina."],["1hqqxx1p1","What does pancreatic elastase in stool measure?","Exocrine pancreatic function; low in pancreatic insufficiency.","Função pancreática."],["iz2j521o6","What does fecal fat (Sudan stain) measure?","Steatorrhea from fat malabsorption.","Esteatorreia."],["m9khigd2m","What is the main inhibitory transmitter of GI smooth muscle?","Nitric oxide and VIP.","Óxido nítrico e VIP."],["1melb5316","What is the main excitatory transmitter of GI smooth muscle?","Acetylcholine (and substance P).","Acetilcolina."],["gkbv3x1sa","What are slow waves in GI smooth muscle?","Rhythmic oscillations in membrane potential generated by interstitial cells of Cajal; set the maximum frequency of contractions.","Ritmo das células de Cajal."],["1rckyzj5u","What are interstitial cells of Cajal and which tumor arises from them?","Pacemaker cells of the GI tract; gastrointestinal stromal tumor (GIST, c-KIT positive).","Células de Cajal; GIST."],["1uhxbij1q","What is the frequency of slow waves in stomach vs duodenum?","Stomach about 3/min; duodenum about 12/min; ileum about 8-9/min.","Estômago 3/min; duodeno 12/min."],["18etnm15z","What is the role of the pyloric sphincter?","Regulates gastric emptying and prevents duodenal reflux.","Regula o esvaziamento."],["1psiilswx","What is chyme?","Semiliquid mixture of food and gastric secretions.","Mistura de alimento e suco gástrico."],["dsjufo1k9","Why does gastric emptying slow after a fatty meal?","CCK release in the duodenum inhibits gastric emptying.","CCK inibe o esvaziamento."],["11joukn1v","What is the role of the lower esophageal sphincter tone?","Maintained by myogenic tone and vagal cholinergic input; relaxed by VIP and NO.","Tônus miogênico e vagal."],["11szdcj1q","What is dumping syndrome?","Rapid gastric emptying after gastric surgery: osmotic diarrhea, cramping, vasomotor symptoms (early); reactive hypoglycemia (late).","Esvaziamento rápido após cirurgia."],["1sq5nvp8z","What is hepatic first-pass metabolism?","Oral drugs absorbed from the GI tract pass through the liver via the portal vein before reaching systemic circulation, reducing bioavailability.","Metabolismo hepático antes da circulação."],["c97cnrntr","What is the enterohepatic circulation of drugs?","Drugs excreted in bile can be reabsorbed in the intestine, prolonging their effect.","Droga volta do intestino ao fígado."],["sy8m0fcoe","Which vitamin is synthesized by gut bacteria and important for coagulation?","Vitamin K.","Vitamina K."],["2m27aq16r","How does the stomach protect itself from acid?","Mucus and bicarbonate layer, tight junctions, prostaglandins (increase mucus, bicarbonate, blood flow), rapid cell turnover.","Muco, bicarbonato, prostaglandinas."],["fw3pebhac","Why do NSAIDs cause gastric ulcers?","Inhibit COX, decreasing protective prostaglandins (PGE2).","AINE reduz prostaglandinas."],["102moaosq","What is the role of prostaglandins in the stomach?","Increase mucus and bicarbonate secretion, increase mucosal blood flow, decrease acid secretion.","Protegem a mucosa."],["1gkx6ao20","What happens to gastric acid production with H. pylori infection of the antrum?","Increased gastrin and acid (duodenal ulcers).","Antro: mais ácido."],["1gv8nslw4","What happens to gastric acid production with H. pylori pangastritis or body atrophy?","Decreased acid (atrophic gastritis), increased risk of gastric cancer.","Atrofia: menos ácido."],["18w811ecm","How does vagotomy affect gastric acid?","Decreases acid secretion (abolishes cephalic phase) and impairs gastric emptying.","Reduz o ácido."],["1ihofooo2","How is vitamin B12 released from food?","Gastric acid and pepsin free it; it binds haptocorrin (R factor), then intrinsic factor after pancreatic proteases cleave haptocorrin.","Ácido libera; liga ao fator intrínseco."],["1ghkqjs1c","Why does pancreatic insufficiency impair B12 absorption?","Pancreatic proteases are needed to release B12 from haptocorrin.","Proteases liberam a B12."],["1mcmwuf1i","What is the role of enterochromaffin-like cells?","Release histamine in response to gastrin, stimulating parietal cells.","Liberam histamina."],["1h4fp7o6i","What does a positive hydrogen breath test indicate?","Carbohydrate malabsorption (lactose intolerance) or small intestinal bacterial overgrowth.","Má absorção ou supercrescimento."],["1k89kxigo","What is small intestinal bacterial overgrowth?","Excess bacteria in the small bowel causing bloating, diarrhea, B12 deficiency (bacteria consume B12), high folate.","Bactérias no intestino delgado."],["1yiv4sm3n","Why is folate elevated in small intestinal bacterial overgrowth?","Bacteria synthesize folate.","Bactérias produzem folato."],["vz1d101fv","What does the stomach absorb?","Little: some water, alcohol, aspirin, lipid-soluble drugs.","Pouco: água, álcool, aspirina."],["dqgfjk1an","What are the two pathways of iron absorption?","Heme iron (via heme carrier protein) and nonheme iron (Fe3+ reduced to Fe2+ by duodenal cytochrome b, then DMT1).","Heme e não heme."],["x9wky8yaq","What is the function of hepcidin in iron absorption?","Degrades ferroportin, blocking iron export from enterocytes and macrophages.","Hepcidina bloqueia ferroportina."],["1111am1lo","What causes pigmented gallstones?","Hemolysis (black stones) or biliary infection (brown stones).","Hemólise ou infecção."],["18jnyga1i","What causes cholesterol gallstones?","Supersaturation of bile with cholesterol, decreased bile acids, gallbladder hypomotility (pregnancy, fasting, obesity, rapid weight loss, estrogen, fibrates).","Excesso de colesterol e estase."],["te96avgzu","Mnemonic for cholesterol gallstone risk factors?","Female, Fat, Fertile, Forty (and Fair).","Mulher, obesa, fértil, 40 anos."],["17qbrma1l","What is the role of the hepatic macrophage system in bilirubin?","Kupffer cells and splenic macrophages break down heme to biliverdin then bilirubin.","Macrófagos degradam o heme."],["s16h1217a","What is physiologic jaundice of the newborn?","Mild unconjugated hyperbilirubinemia from immature UGT activity and increased RBC turnover; resolves in 1-2 weeks.","Icterícia fisiológica."],["muldr64b2","Why does breast milk jaundice occur?","Increased beta-glucuronidase in breast milk deconjugates bilirubin, increasing enterohepatic circulation.","Leite desconjuga bilirrubina."],["6kxssgpen","What is breastfeeding failure jaundice?","Insufficient breast milk intake decreases bilirubin elimination in stool, increasing enterohepatic circulation in the first week.","Pouco leite na primeira semana."],["1s3h5vb1f","What is kernicterus?","Unconjugated bilirubin deposition in the basal ganglia causing neurologic damage; prevented with phototherapy (converts bilirubin to water-soluble isomers).","Bilirrubina nos núcleos da base."],["1ooi05apz","Which hepatic process is most affected by hepatocyte zone III location?","Cytochrome P450 drug metabolism.","Metabolismo pelo CYP450."],["1o3bjam6o","What is the role of glutathione in the liver?","Conjugates toxic metabolites such as NAPQI from acetaminophen.","Neutraliza NAPQI."],["1ylmudf1l","What is the role of the liver in hormone metabolism?","Inactivates estrogen, aldosterone, insulin, and other hormones; cirrhosis causes hyperestrogenism (gynecomastia, spider angiomas, palmar erythema).","Inativa hormônios."],["1t66w1e58","Why do patients with cirrhosis have gynecomastia and spider angiomas?","Decreased hepatic metabolism of estrogen and increased conversion of androgens to estrogens.","Menos degradação de estrogênio."],["1ng9lu25o","What is the main stimulus for bile secretion from hepatocytes?","Bile acids returning via enterohepatic circulation (and secretin for bicarbonate-rich bile).","Ácidos biliares."],["14z26ja1j","What is the function of colipase?","Anchors pancreatic lipase to fat droplets in the presence of bile salts.","Fixa a lipase."],["5jsljx1pu","What digests proteins at the brush border?","Peptidases (aminopeptidases, dipeptidases); amino acids, di- and tripeptides are absorbed.","Peptidases."],["g1cgzu1uk","What digests disaccharides at the brush border?","Lactase, sucrase-isomaltase, maltase.","Lactase e sacarase."],["1g83howe9","What is the most common disaccharidase deficiency?","Lactase deficiency.","Lactase."],["q1j72517h","How does secretin protect the duodenum?","Increases pancreatic bicarbonate secretion and decreases gastric acid secretion, neutralizing acidic chyme.","Bicarbonato e menos ácido."],["12a86a4wb","What is the effect of somatostatin on splanchnic blood flow and its clinical use?","Decreases splanchnic and portal blood flow; octreotide is used to control variceal bleeding.","Octreotida nas varizes."],["tj0hk31h1","What is the primary function of the large intestine?","Water and electrolyte absorption, storage and elimination of feces.","Absorver água."],["174fdct75","What is the total daily fluid entering the GI tract and how much reaches stool?","About 9 L enters (diet and secretions); about 100-200 mL is lost in stool.","9 L entram; 100-200 mL saem."]]}];
